(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-jax-mesh-parallel-video"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-1\">一 · 一个把 SLO 打穿的事故：从单卡勉强跑到多卡反而更慢</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-2\">二 · 问题的确切形状：显存墙、时延墙与阶段错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-3\">三 · 它明确不解决的问题：边界画在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-4\">四 · 失败模式的解剖：通信、重排与重编译三条路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-5\">五 · 与相邻算法的分工：为什么不是张量并行、也不是分块重叠</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-6\">六 · 适用边界的量化判据：什么时候该上、什么时候该退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-7\">七 · 序列切分：从 latent 张量到 mesh 轴的落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-8\">八 · 注意力阶段：本地 QKV、环形交换与 WGMMA 重叠</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-9\">九 · FFN 与残差：本地 GEMM 后的 all-reduce</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-10\">十 · 阶段切换：latent 按帧重排到数据并行轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-11\">十一 · 编译期融合与重编译代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-12\">十二 · 按序列长度设分片上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-13\">十三 · 失效边界：序列并行在什么条件下从收益翻成负债</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-14\">十四 · 时延主公式的逐项拆解与主导项判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-15\">十五 · 序列并行注意力的分块推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-16\">十六 · FFN 与残差的通信-计算配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-17\">十七 · 阶段切换的重排代价与编译期融合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-18\">十八 · 分片上限、批上限与重编译的联合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-19\">十九 · 边界：通信项何时吃掉整条流水线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-20\">二十 · 请求形态：什么样的负载才吃得到序列并行的收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-21\">二十一 · 长度分布：切分上限由最长序列而非平均长度决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-22\">二十二 · 并发与批大小：批是通信缓冲的乘数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-23\">二十三 · 负载不对时的三种塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-24\">二十四 · 配方与 SLO 的对应：把时延下限算清楚再定并行度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-25\">二十五 · 负载配方：长序列固定步数才是它的舒适区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-26\">二十六 · 硬件档位：从单节点八卡到多节点 NVL72 的分档判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-27\">二十七 · 并行拓扑：序列轴乘张量轴的二维 mesh 与 VAE 数据并行轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-28\">二十八 · 量化方案：分片激活与权重的精度分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-29\">二十九 · KV 策略：按序列分片本地持有，拒绝跨请求共享</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-30\">三十 · 调度参数：批上限、编译缓存与分片上限的三角折中</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-31\">三十一 · 可复现的配置思路：从容量不等式反推 mesh</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-32\">三十二 · 配方失效的四个断点与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-33\">三十三 · 从 roofline 到 mesh roofline：代价函数的形状变了</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-34\">三十四 · 显存：分片把峰值搬到通信缓冲上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-35\">三十五 · 带宽：HBM 与互联是两条不同的紧约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-36\">三十六 · 功耗与热：并行不降低总能量，只改变分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-37\">三十七 · 尾延迟：重编译与布局失配是尖峰的两个来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-38\">三十八 · 规模上限由谁决定：互联与编译可行性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-39\">三十九 · 规模上去以后，先崩的是跨节点带宽与编译缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-40\">四十 · 精度漂移：从分片边界到跨阶段累积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-41\">四十一 · OOM 的三条来源与显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-42\">四十二 · 批抖动与重编译尖峰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-43\">四十三 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-44\">四十四 · 监控面与回滚阶梯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-45\">四十五 · 序列切分越界之后：通信、重排与重编译的三类尖刺怎么定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-46\">四十六 · 对照轴：先分清“切什么”与“切在哪一层”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-47\">四十七 · 决策表：五种形态的适用条件与代价落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-48\">四十八 · 选型判据：三个可计算的比值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-49\">四十九 · 与分块重叠的接缝：窗口问题不等于容量问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-50\">五十 · 与量化、稀疏、缓存的组合次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-51\">五十一 · 规模上限与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-jax-mesh-parallel-video-sec-52\">五十二 · 选型边界：序列并行、时间分块与朴素张量并行的三岔口</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:550px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 550.4 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"468.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">把latent序列按帧/空间块切到mesh的序列并行轴，权重按头/通道切到…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"468.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">注意力QKV本地计算后做all-gather/ring交换KV，WGMMA…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"468.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">FFN本地GEMM后做all-reduce，残差在本地累加。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"468.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样完成latent按帧重排到数据并行轴做VAE解码，避免跨节点传输像素。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"468.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用JAX sharding annotation统一布局，编译期融合重排与…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-jax-mesh-parallel-video-sec-1\">一 · 一个把 SLO 打穿的事故：从单卡勉强跑到多卡反而更慢</h3>\n<p>某视频生成服务把一条 1080p、固定 48 步采样的 DiT 推理链路从单卡 A 切到 8 卡单节点。上线前的判断很朴素：单卡显存已经贴着上限跑，latent 序列再长一点就 OOM，多卡至少能把显存摊开。上线后监控给出的曲线却相反：端到端时延没有下降，尾帧时延反而出现尖峰，跨节点流量在高峰期把 IB 打满，GPU 利用率掉到低位。根因不是算力不够，而是并行方式选错了——团队沿用了训练侧的朴素张量并行，把权重按通道切碎，每一层 FFN 之后都要做一次全量 all-reduce，注意力层则把完整 KV 复制到每张卡。序列越长，这份被复制的 KV 越大，通信量随序列长度线性膨胀，而 WGMMA 的计算时间几乎不变，于是 $T_{\\text{step}}$ 被通信项牢牢钉住。更糟的是，采样阶段结束后的 latent 要交给 VAE 解码，VAE 走的是另一套按帧切分的布局，两个阶段之间发生了一次运行期全量重排，latent 在设备间来回搬运，显存峰值和同步开销同时抬升。这个事故说明：视频 DiT 的多卡推理不是“把模型切开”就完事，切哪个维度、阶段之间怎么衔接，决定了通信是藏在计算背后还是压在关键路径上。</p>\n<p>本片段要界定的，正是加速器网格并行视频推理这一类算法解决的问题域：它针对的是高分辨率、长时长、固定步数的视频 DiT 推理，在单卡显存放不下或单卡时延不达标时，用多卡乃至多节点的网格并行把 latent 序列与权重分摊开，并让采样与 VAE 两个阶段各自使用合适的并行轴。它不解决短序列、小模型下的吞吐优化，也不解决单卡内部的窗口突破问题——后者属于时间分块重叠那条线，这里只用一句话指路：分块重叠靠时间维切分加重叠融合把注意力窗口压进单卡，而网格并行靠设备维切分把整条序列摊到多卡。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-2\">二 · 问题的确切形状：显存墙、时延墙与阶段错配</h3>\n<p>把问题拆成三条约束，才能判断一个部署该不该上这套算法。第一条是显存墙：高分辨率长视频的 latent 序列长度随帧数与空间分辨率同时增长，注意力窗口内的 QKV 激活、以及按序列分片本地持有的 KV，会迅速吃掉单卡容量。第二条是时延墙：即便显存勉强够，单卡的张量核心吞吐也撑不住固定步数采样的端到端 SLO，尤其是流式场景要求首帧与后续帧的间隔稳定。第三条是阶段错配：采样阶段的计算形态是序列维上的注意力和逐 token 的 FFN，天然适合按序列切分；VAE 解码的计算形态是按帧独立的卷积式重建，天然适合按帧做数据并行。如果强行让两个阶段共用一套布局，阶段边界上必然出现全量重排。</p>\n<p>用给定的代价模型可以把这三条约束写成一句判断：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right),\\quad \\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</div>\n<p>其中 $N$ 是序列长度，$P_s$ 是序列并行轴的切分数，$d$ 是头维度，$N_h$ 是头数。这个式子给出的工程判断很直接：当序列很长、$P_s$ 又不够大时，第二项的通信分量会超过第一项的计算分量，加卡不再降低单步时延，只是把瓶颈从张量核心搬到互联。反过来，如果 $P_s$ 开得足够大、单卡分片足够短，计算项重新占主导，加卡才有意义。事故里的团队恰恰处在第一种情形：他们切的是权重维而不是序列维，$P_s$ 名义上等于 1，$\\text{Comm}_{\\text{attn}}$ 随 $N$ 一路涨。</p>\n<p>一个具体的适用例子：某部署要在 8 卡单节点上跑 1080p、数十帧的 DiT 采样，latent 序列按帧与空间块切到序列并行轴，权重按头与通道切到张量并行轴，注意力阶段 QKV 本地算完后用 ring 交换 KV，WGMMA 与 NVLink 传输重叠，FFN 本地 GEMM 后做 all-reduce、残差本地累加。这个配方之所以成立，是因为序列维可切、且切分后每卡的注意力块仍能独立完成 softmax 归一化，通信只发生在 KV 交换这一处。若换成短序列、小模型，同样的 8 卡切分会让每卡分片短到 WGMMA 利用率不足，通信开销反超收益，这时该退回单卡或更小的并行度。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-3\">三 · 它明确不解决的问题：边界画在哪里</h3>\n<p>这套算法的收益随序列长度与分辨率增大，边界也由同一组变量决定。第一，规模上限由跨节点互联带宽与编译可行性共同决定。单节点内 NVLink 域内做序列并行，通信可以被 WGMMA 重叠掩盖；一旦序列切分跨到多节点，KV 的 all-gather 或 ring 交换要过 IB，带宽成为时延下限，此时继续增大 $P_s$ 只会让 $\\text{Comm}_{\\text{attn}}$ 中的跨节点分量压过计算。第二，它不解决动态 batch 与变长请求带来的编译开销：JAX 的 sharding annotation 在编译期融合重排与通信，布局一旦随请求形态变化就要重编译，编译缓存未命中时首帧时延出现尖峰，流式 SLO 在负载波动下守不住。第三，它不替代量化与内核层面的优化——FP8/NVFP4 降低分片激活与权重占用、稀疏时空注意力降低窗口内计算量，这些是另外条目的主题，网格并行只负责把剩余的工作量摊到设备维上；两者叠加时，量化让每卡分片更小，反而可能让序列切分数目成为新的约束。</p>\n<p>还有一条容易误判的边界：它不解决跨块或跨请求的 KV 共享。按序列分片本地持有的 KV 不跨块共享，是为了避免 all-gather 规模随共享范围膨胀。如果业务侧希望多个请求复用同一段视频前缀的 KV，那是缓存复用条目的问题，网格并行在这里只会把共享的 KV 复制到每个序列分片上，通信量按分片数放大。工程上判断是否该上这套算法，可以看三个信号：单卡显存已贴上限且序列还会增长；端到端时延在单卡上无法压进 SLO；采样与 VAE 的布局冲突已经在监控上表现为阶段边界的显存尖峰与同步等待。三者缺一，收益都可能被通信或编译开销吃掉。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-4\">四 · 失败模式的解剖：通信、重排与重编译三条路径</h3>\n<p>失败模式一，序列切分过多压垮跨节点带宽。机制上，注意力阶段每个设备本地算出 QKV 后，需要拿到全部 KV 才能算完整的 softmax 归一化，ring 交换的轮数与 $P_s$ 同阶，每轮搬运的数据量正比于 $\\frac{N}{P_s}\\,d\\,N_h$。当 $P_s$ 增大到跨节点，单轮数据虽小但轮数多、且每轮都要等 IB 往返，重叠窗口被切碎，WGMMA 空转。代价体现在时延上：单步时延不再随加卡下降，尾帧抖动放大。一个具体例子是把 8 卡单节点扩到 16 卡双节点后，序列并行轴跨了节点边界，KV 交换从 NVLink 域内变成 IB 域间，端到端时延不降反升，这正是事故里那条尖峰曲线的来源。</p>\n<p>失败模式二，sharding 布局在采样与 VAE 阶段不一致导致运行期全量重排。机制上，采样阶段 latent 沿序列并行轴切分，VAE 解码按帧走数据并行轴，如果两阶段的 annotation 没有统一，编译期融合失败，运行期就要把 latent 从序列布局整体搬到帧布局，搬运量正比于整段 latent 的体积，且伴随设备间同步。代价是显存峰值抬升与阶段边界的同步等待，流式场景下表现为帧间间隔的规律性抖动。正确的做法是在编译期用统一的 sharding annotation 把重排与通信一起融合，让 latent 按帧直接落到数据并行轴，避免像素跨节点传输。</p>\n<p>失败模式三，动态 batch 与变长请求触发频繁重编译。机制上，序列长度与批大小进入编译键，请求形态一变就产生新的编译产物，编译缓存未命中时首帧时延出现尖峰。代价是流式 SLO 在负载波动下失守，且编译本身占用主机侧资源。工程折中是设批上限与序列分片上限，把请求形态收敛到有限几种编译键，用编译缓存覆盖常见形态，超出上限的请求走降级路径而不是触发新编译。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-5\">五 · 与相邻算法的分工：为什么不是张量并行、也不是分块重叠</h3>\n<p>与朴素张量并行的差别不在“切不切”，而在切哪个维、通信落在哪里。朴素张量并行把权重按通道切碎，每层 FFN 后全量 all-reduce，注意力层复制完整 KV，通信量随序列长度增长而计算量不变，事故正是这个形态。网格并行把序列维切到序列并行轴、权重切到张量并行轴，注意力只交换 KV 而非复制完整激活，且交换与 WGMMA 重叠，$\\text{Comm}_{\\text{attn}}$ 中的 $N$ 被 $P_s$ 除掉，通信随切分数而非序列长度膨胀。与分块重叠的分工更清楚：分块重叠在单卡内用时间分块加重叠融合突破注意力窗口，网格并行在设备维上突破显存与窗口，两者可以叠加——分块把每卡窗口压小，网格并行再把剩余序列摊到多卡，但叠加时要注意分片上限与通信缓冲的显存占用。</p>\n<p>与阶段差异化并行相关的另一条线是预填解码分离服务，那条线切的是请求内的阶段（预填与解码）到不同资源池，网格并行切的是同一阶段内的序列维到不同设备，二者解决的不是同一个瓶颈。一个具体判断：如果瓶颈在单条长视频的显存与窗口，用网格并行；如果瓶颈在混合负载下预填挤占解码的时延，用分离式服务；如果瓶颈在单卡窗口内的计算密度，用分块重叠或稀疏注意力。三条线的代价分别落在互联带宽、资源池调度与单卡算力上，混用时要分别核算，不能指望一条线同时解决三个瓶颈。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-6\">六 · 适用边界的量化判据：什么时候该上、什么时候该退</h3>\n<p>把边界写成可操作的判据，需要把代价模型落到部署参数上。给定序列长度 $N$、序列并行切分 $P_s$、单卡分片显存上限与通信缓冲，先估每卡分片长度 $\\frac{N}{P_s}$ 是否仍能让 WGMMA 保持足够长的计算段以掩盖一次 KV 交换；若不能，说明 $P_s$ 过大或互联太慢。再估跨节点分量：若序列并行轴跨节点，KV 交换的往返时延与轮数相乘后是否已接近单步时延的量级；若是，说明该把序列并行限制在单节点 NVLink 域内，跨节点改用数据并行或把长视频拆成流式分块。最后估编译可行性：请求形态的种类数是否收敛到可缓存的规模，动态 batch 的上限是否与显存分片匹配；若形态发散，先收敛形态再谈并行。</p>\n<p>一个具体的退让例子：某部署原计划 32 卡跨四节点做序列并行，按上式估算后发现 $\\frac{N}{P_s}$ 已短到 WGMMA 段不足以掩盖一次 IB 往返，且请求形态有十余种、编译缓存命中率低。工程判断是退回单节点 8 卡序列并行加时间分块重叠，跨节点只做请求级数据并行，把长视频按流式分块送入，牺牲单条视频的极限分辨率换取 SLO 稳定。这个判断的依据不是“卡多就好”，而是代价模型里通信项与计算项的相对大小，以及编译键的收敛程度。适用边界的本质是一句工程话：序列维可切、互联够快、请求形态可编译，三者同时成立时这套算法才划算；缺一条，就该换轴或换算法，而不是继续加卡。</p>\n<h3 id=\"alg-jax-mesh-parallel-video-sec-7\">七 · 序列切分：从 latent 张量到 mesh 轴的落位</h3>\n<p>整条流水线的第一步不是计算，而是布局决策：把一段形状为 <code>[F, H, W, C]</code> 的 latent 序列映射到 JAX mesh 的序列并行轴上。切法有两种正交选择——按帧切（时间维）或按空间块切（把每帧的 H×W 网格划成若干 tile）。按帧切的好处是每张卡持有完整空间结构，注意力窗口的时空邻域关系不被破坏，但单帧分辨率极高时单卡仍放不下；按空间块切则把每帧切成 <code>P_s</code> 份，每卡持有全部帧的一个空间条带，显存压力被摊薄，代价是跨块注意力必须在设备间交换 KV。工程上常取混合切分：时间维切 <code>P_t</code>、空间维切 <code>P_s</code>，序列并行轴大小 <code>P_seq = P_t × P_s</code>，与张量并行轴 <code>P_tp</code> 相乘构成完整 mesh。</p>\n<p>这一步的输入是主机侧传入的 latent 与 sharding annotation，输出是每卡本地的分片张量及其 halo 区域索引。代价主要落在两处：一是切分后的分片必须满足每卡显存预算，分片激活加上通信缓冲（ring 交换需要双缓冲 KV 暂存）共同决定批大小上限；二是切分粒度直接决定后续通信量，切得越细，每卡计算越少而交换越频繁。用公式表达单步时间下界：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right),\\quad \\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</div>\n<p>其中 <code>N</code> 为序列长度、<code>d</code> 为头维度、<code>N_h</code> 为头数。可以看到通信项与 <code>N/P_s</code> 成正比：切分数 <code>P_s</code> 增大时分母变大、单卡通信量下降，但设备数增加使总交换轮次上升，跨节点时 IB 带宽成为硬下限。一个具体例子：一段 1080p、数十帧的 latent 在单节点 8 卡上按 <code>P_t=2, P_s=4</code> 切分，每卡持有约 1/8 的 token，注意力窗口完整落在本地帧组内，跨组边界只需交换 halo 帧的 KV，通信缓冲远小于全量 all-gather。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-8\">八 · 注意力阶段：本地 QKV、环形交换与 WGMMA 重叠</h3>\n<p>进入注意力计算，每卡先用本地分片算出 Q、K、V，这一步是纯本地 GEMM，无通信。真正的机制在于 KV 的获取方式：all-gather 让每卡拿到全局 KV 后独立算完整注意力，实现简单但通信量随设备数线性膨胀且需要大块暂存；ring 交换则把 KV 沿设备环逐跳传递，每卡在收到一跳 KV 后立即计算对应块的局部注意力并累加，通信与计算被流水化。Blackwell 上的关键是把 tcgen05 的 WGMMA 与 NVLink 传输放在不同流水级：当第 <code>i</code> 跳的 KV 正在链路上时，第 <code>i-1</code> 跳的局部注意力已在 tensor core 上跑完，二者通过异步屏障同步而非全局等待。</p>\n<p>局部注意力的数学形式不变，只是作用域被切片：</p>\n<div class=\"formula\">$$\\text{Attn}(Q,K,V)=\\text{softmax}\\left(\\frac{QK^{\\top}}{\\sqrt{d}}\\right)V$$</div>\n<p>其中 <code>Q,K,V</code> 按序列轴切分到各设备，<code>K,V</code> 经 ring 或 all-gather 交换后本地计算局部注意力块。工程上必须处理 softmax 的数值稳定性：分块累加需要维护 running max 与 running sum，否则跨块归一化会引入偏差。这一步的输出是每卡本地的注意力结果分片，代价集中在通信带宽与暂存显存——ring 交换需要至少两跳的 KV 缓冲，all-gather 则需要 <code>P_seq</code> 倍于本地 KV 的暂存，后者在长序列下会直接吃掉分片激活的显存余量。一个可操作的判断：当 <code>N/P_s</code> 仍远大于单跳传输粒度时，ring 的流水化收益明显；当序列切分很细、每跳数据量小于链路启动开销时，ring 的固定开销反而拖慢单步。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-9\">九 · FFN 与残差：本地 GEMM 后的 all-reduce</h3>\n<p>注意力输出进入 FFN 前，若权重按张量并行轴切分（按头或按通道），则每个 FFN 层是一次本地 GEMM 加一次跨张量并行轴的 all-reduce。这里的顺序很重要：残差必须在本地累加后再参与归约，否则归约后的数值与单卡路径不一致，长步数采样会累积漂移。Blackwell 的 TMEM 在这里承担累加器角色，GEMM 的部分和留在 tensor memory 中，all-reduce 只搬运最终分片，避免中间结果反复落 shared memory。</p>\n<p>这一步的代价是双重的：all-reduce 的字节数与隐藏维度成正比，跨节点时与注意力 KV 交换共享同一条 NVLink/IB 通道，两者叠加会推高单步通信项；同时 FFN 的本地 GEMM 若因张量并行切分导致每卡矩阵过小，tensor core 利用率下降，计算项反而变长。伪代码思路是：<code>y_local = GeMM(x_local, W_shard); y = all_reduce(y_local, axis=tp); out = x_local + y</code>，其中 <code>x_local</code> 是序列分片、<code>W_shard</code> 是通道切片。一个具体例子：隐藏维较大时按通道切 <code>P_tp=2</code> 或 <code>4</code>，每卡 GEMM 仍能喂满 WGMMA 的 tile 形状；若切到 <code>8</code> 以上，单卡矩阵瘦到无法填满流水线，计算项成为瓶颈，此时应把设备更多分配给序列轴而非张量轴。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-10\">十 · 阶段切换：latent 按帧重排到数据并行轴</h3>\n<p>采样循环结束后，latent 需要交给 VAE 解码。这是整条流水线最容易出问题的一步：采样阶段的布局是序列并行轴持有空间条带，而 VAE 解码天然按帧独立，最省的布局是数据并行轴——每卡拿整帧像素做解码，像素永不跨节点。若两个阶段共用同一 mesh 布局，解码时每卡只持有条带，必须先把条带拼回整帧，这个重排要么走跨节点传输，要么在本地做昂贵的 gather/scatter。</p>\n<p>机制上的解法是用 sharding annotation 声明两个阶段的布局，让编译器在阶段边界插入重排，并把重排与相邻算子融合。输入是序列分片的 latent，输出是数据并行轴上的整帧 latent，代价是重排本身的通信量与同步开销：若重排退化为运行期全量搬运，latent 在设备间反复流动，显存峰值与同步延迟同时上升。一个具体例子：<code>P_seq=8</code> 的条带布局切到 <code>P_dp=8</code> 的帧布局，若每卡恰好持有一整帧的条带集合，重排可退化为本地拼接、零跨节点流量；若切分与帧边界不对齐，则必须跨节点搬运，此时应调整切分粒度使条带边界与帧边界重合。这一步的工程判断是：切分策略在采样阶段就要为解码阶段预留对齐，而不是事后补救。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-11\">十一 · 编译期融合与重编译代价</h3>\n<p>统一编译是这套机制区别于手工拼装并行方案的核心。JAX 在 trace 阶段看到完整的 sharding annotation，能把重排、通信与相邻 GEMM 融合进同一个编译单元，通信指令被调度到计算流水的空隙里。但编译不是免费的：动态 batch 与变长请求会改变张量形状，触发重编译；编译缓存未命中时首帧时延出现尖峰，流式 SLO 在负载波动下难以守住。稳定性技巧是在编译缓存与批上限之间折中——把批大小分桶到有限档位，变长序列按长度区间归并，用少量重编译换取缓存命中率。</p>\n<p>这一步的代价是编译时间与内存占用：每个桶位对应一份编译产物，桶位过多会撑爆主机内存与编译队列；桶位过少则形状不匹配导致填充浪费，序列分片的有效利用率下降。一个具体例子：把批大小固定为少数几档、序列长度按帧数归并，使采样与 VAE 两阶段共享同一批编译产物，避免阶段间因布局不同而各自重编译。失败模式很明确：sharding 布局在采样与 VAE 阶段不一致时，编译期融合失败会退化为运行期全量重排，latent 在设备间反复搬运，显存与同步开销陡增。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-12\">十二 · 按序列长度设分片上限</h3>\n<p>整条流水线的最后一个工程动作是给序列切分设上限。切分越多，单卡显存越松，但通信项随设备数上升，跨节点 IB 带宽成为时延下限；切分过少则单卡注意力窗口放不下。上限的确定方式是解一个约束：在给定互联带宽下，使 <code>Comm_attn</code> 与 <code>Comm_ffn</code> 之和不超过计算项，即通信不成为主导。由于 <code>Comm_attn ∝ N/P_s</code>，序列越长，允许的 <code>P_s</code> 越大，但设备数受集群规模约束，最终由 <code>N/P_s</code> 的最小可接受粒度反推 <code>P_s</code> 上限。</p>\n<p>KV 按序列分片本地持有、跨块或跨请求不共享，是控制 all-gather 规模膨胀的关键：若把 KV 做成全局共享池，all-gather 的规模会随并发请求数叠加，通信缓冲迅速吃掉显存。一个具体例子：多请求并发时，每个请求的 KV 只在其序列分片内可见，注意力交换只在单请求的 mesh 子集内进行，跨请求不产生额外通信；代价是设备利用率随请求数波动，需要在批调度层做请求与 mesh 子集的配对。最终判断落在互联拓扑上：单节点内 NVLink 带宽充裕时序列切分可激进，跨节点时切分上限由 IB 带宽与 ring 跳数共同决定，超过该上限的收益被通信开销吞掉。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-13\">十三 · 失效边界：序列并行在什么条件下从收益翻成负债</h3>\n<p>这一节的判断标准只有一条：序列并行省下的显存与注意力窗口，是否大于它新增的通信与编译开销。把注意力写成按序列轴切分的局部块形式 <span class=\"formula\">$$\\text{Attn}(Q,K,V)=\\text{softmax}\\left(\\frac{QK^{\\top}}{\\sqrt{d}}\\right)V$$</span> 之后，每个设备只持有 $Q,K,V$ 的一段，但要算出完整注意力仍需把 $K,V$ 通过 ring 或 all-gather 在设备间交换，通信量随序列切分数成正比。这意味着切分不是免费的：切得越细，单卡分片越小、显存越松，但交换次数与跨节点流量同步上升。当序列切分轴跨出单节点、落到 IB 上时，$\\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$ 里的 $P_s$ 增大不再带来等比例的时间收益，反而把时延下限钉在互联带宽上，WGMMA 与 NVLink 的重叠只能掩盖节点内那一段。</p>\n<p>第二个失效点是布局不一致导致的编译期融合失败。采样阶段 latent 切在序列并行轴、VAE 解码按帧切在数据并行轴，两者靠 JAX sharding annotation 统一布局、由编译器把重排与通信融进 kernel；一旦动态 batch 或变长请求让形状偏离已编译的静态图，融合退化为运行期全量重排，latent 在设备间反复搬运，显存峰值与同步开销同时抬升。这类退化不会报错，只表现为首帧时延尖峰，流式 SLO 在负载波动下先崩的往往就是这一环。编译缓存命中率因此是比峰值算力更值得监控的指标。</p>\n<p>第三个边界是收益随规模反转。小模型或短序列下，并行通信开销可能超过收益；序列切分过多使通信成为瓶颈；规模上限由跨节点互联带宽与编译可行性共同决定，而不是由卡数决定。下表给出三类形态的定性判断，用于在部署前决定是否启用序列并行轴。</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>主瓶颈</th><th>并行轴选择</th><th>主要代价</th></tr></thead><tbody><tr><td>高分辨率长视频、多节点</td><td>跨节点 IB 带宽</td><td>序列并行 × 张量并行，VAE 走数据并行</td><td>KV 交换随长度增长，编译调优成本高</td></tr><tr><td>中等分辨率、单节点多卡</td><td>NVLink 带宽与显存</td><td>序列并行轴收窄，张量并行补足</td><td>节点内 all-gather 可与 WGMMA 重叠</td></tr><tr><td>短序列或小模型</td><td>通信开销本身</td><td>不启用序列并行</td><td>并行收益被通信吃掉</td></tr></tbody></table>\n<p>工程判断落在分片上限的设置上：按序列长度设一个显式的切分上限，使每卡分片的 KV 缓冲与通信缓冲都落在预算内，同时把批上限压到编译缓存能覆盖的形状集合里；量化用 FP8/NVFP4 降低分片激活与权重占用，可以在不加深切分的前提下换回显存余量，从而把 $P_s$ 停在互联带宽仍可承受的区间。KV 按序列分片本地持有、跨块与跨请求不共享，是避免 all-gather 规模随批膨胀的必要约束——一旦允许跨请求共享 KV，交换量就不再只由单条序列长度决定。</p>\n<h3 id=\"alg-jax-mesh-parallel-video-sec-14\">十四 · 时延主公式的逐项拆解与主导项判定</h3>\n<p>把一次去噪步的墙钟时间写成两个下界的取大，是这套并行方案所有调参决策的出发点：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right),\\quad \\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</div>\n<p>第一项是计算下界：分子为该步的有效浮点运算量，分母是参与设备数 $P$ 与单设备张量核心持续吞吐 $\\text{TC}$ 的乘积。注意 $\\text{TC}$ 必须取<em>可持续</em>值而非峰值——WGMMA 在 tcgen05 路径上的实际占用率取决于 TMEM 容量与流水深度，长序列注意力里 softmax 的 SFU 占用会把有效 $\\text{TC}$ 拉低。第二项是存储与互联下界：$\\text{Bytes}$ 是该步必须搬动的字节数（分片权重、分片激活、KV 分片），$\\text{BW}$ 是单卡 HBM 带宽，$\\text{Comm}$ 是跨设备交换量，$\\text{NVLink}$ 取该拓扑下的有效单向带宽（节点内 NVLink 5 与跨节点 IB 必须分开代入，不能混用同一个数）。</p>\n<p>推导的关键一步在于：序列并行把 $\\text{FLOPs}$ 与 $\\text{Bytes}$ 都按 $P_s$ 缩小，却<em>不</em>缩小 $\\text{Comm}$——通信量正比于 $N/P_s \\cdot d \\cdot N_h$，即每卡持有的序列分片长度乘以头维度与头数。于是当 $P_s$ 增大，第一项线性下降而第二项里的 $\\text{Comm}$ 项只按 $1/P_s$ 缓慢下降（因为 $N/P_s$ 仍随 $N$ 增长），必然存在一个交叉点，越过它再加卡就是净亏损。工程判断因此不是\"卡越多越快\"，而是先测出本拓扑下 $\\text{Comm}$ 项占第二项的比值，再决定 $P_s$ 上限。</p>\n<p>具体例子：一条高分辨率长视频 latent 序列被切到 8 路序列并行轴上，注意力阶段每卡本地算出 QKV 后需与其余 7 卡交换 KV。若跨节点，交换走 IB 而非 NVLink，$\\text{NVLink}$ 项应替换为 IB 有效带宽，此时第二项往往直接压过第一项——这就是\"跨节点时互联带宽成为时延下限\"的公式来源，而不是经验之谈。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-15\">十五 · 序列并行注意力的分块推导</h3>\n<p>序列轴切分后，全局注意力被改写为对本地查询块与全部键值块的乘积：</p>\n<div class=\"formula\">$$\\text{Attn}(Q,K,V)=\\text{softmax}\\left(\\frac{QK^{\\top}}{\\sqrt{d}}\\right)V$$</div>\n<p>其中 $Q,K,V$ 按序列轴切分到各设备，$K,V$ 经 ring 或 all-gather 在设备间交换后本地计算局部注意力块，$d$ 为头维度。推导的关键一步是 softmax 的数值稳定性处理：本地只能看到部分 $K$，直接对局部 logits 做 softmax 会得到错误的归一化分母。正确做法是维护运行最大值 $m$ 与运行分母 $\\ell$ 的在线更新（ring attention 的经典递推），每收到一个远端 KV 块就更新 $(m,\\ell)$ 并 rescale 已累积的输出。伪代码落到可实现层面大致是：</p>\n<ul>\n<li>本地计算 $S_{\\text{local}} = Q K_{\\text{local}}^{\\top} / \\sqrt{d}$，求块内行最大值 $m_{\\text{blk}}$ 与 $\\ell_{\\text{blk}}=\\sum e^{S-m_{\\text{blk}}}$；</li>\n<li>进入 ring 循环，第 $r$ 步接收邻居的 $K,V$ 分片，算 $S_r$，更新 $m=\\max(m,m_r)$，$\\ell = \\ell e^{m_{\\text{old}}-m} + \\ell_r e^{m_r-m}$，输出 $O \\leftarrow O e^{m_{\\text{old}}-m} + e^{S_r-m}V_r$；</li>\n<li>循环 $P_s-1$ 步后 $O \\leftarrow O/\\ell$ 得到本地查询块的最终输出。</li>\n</ul>\n<p>代价结构很清楚：ring 交换的步数是 $P_s-1$，每步搬运 $N/P_s \\cdot d \\cdot N_h$ 个元素，因此总通信量随 $P_s$ 近似线性增长而单步计算量随 $P_s$ 下降——这正是 $\\text{Comm}_{\\text{attn}}$ 公式的物理含义。系统代价上，ring 的好处是不需要一次性 all-gather 出完整 KV，显存峰值只多一个分片的缓冲；坏处是延迟随环长线性叠加，跨节点时每跳都吃 IB 时延。因此节点内优先用 all-gather 走 NVLink（带宽高、跳数少），跨节点才退化为 ring 并把 WGMMA 与通信流水重叠。</p>\n<p>具体例子：8 卡序列并行、每卡持有一段帧块，注意力阶段若全部 all-gather，则每卡需临时容纳 8 倍于本地的 KV，显存直接爆掉；改用 ring 后每卡只需两份分片缓冲（当前与邻居），代价是 7 步串行通信。重叠的实现方式是把第 $r$ 步的 KV 接收与第 $r-1$ 步的 WGMMA 排在同一流水里，让 NVLink 传输藏在矩阵乘的阴影下。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-16\">十六 · FFN 与残差的通信-计算配比</h3>\n<p>FFN 走的是另一条轴：权重按头或通道切到张量并行轴，本地 GEMM 后做 all-reduce，残差在本地累加。这里的关键推导是 all-reduce 的字节数——每个 token 的隐藏维 $h$ 在每层需要一次跨 $P_t$ 路的归约，量级为 $2 \\cdot \\text{tokens} \\cdot h \\cdot (P_t-1)/P_t$ 字节（ring all-reduce 的经典系数）。与注意力不同，FFN 的通信量与序列长度解耦，只随批内 token 数增长，因此它是<em>批大小</em>的函数而非<em>视频长度</em>的函数。</p>\n<p>这带来一个可直接落地的配比判断：当序列很长、批很小时，注意力通信主导，应把更多设备放到序列并行轴；当批被拉大以提吞吐时，FFN 的 all-reduce 开始压过注意力交换，此时应把设备挪到张量并行轴。残差本地累加是省通信的细节——把残差加法留在分片本地，避免为加法再做一次跨设备同步，代价是每卡需持有完整残差副本，显存占用按 $P_s$ 份复制。</p>\n<p>系统代价上，FFN 的 all-reduce 是延迟敏感型：它卡在每层末尾，无法像注意力那样用长流水掩盖，因此跨节点时它往往成为每层的最短路径瓶颈。工程上把 FFN 的张量并行轴尽量约束在节点内，让 all-reduce 走 NVLink 而非 IB，是把这条路径压到可接受区间的常规手段。具体例子：一个固定步数的视频生成请求，批大小受每卡序列分片显存与通信缓冲约束而很小，此时若把 8 卡平均分给两条轴（4×2），FFN 的 all-reduce 跨了节点边界，每层多出一次 IB 往返，端到端时延被这条路径钉死；改成 8×1 全序列并行、FFN 权重不切，反而更快。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-17\">十七 · 阶段切换的重排代价与编译期融合</h3>\n<p>采样阶段用序列并行轴，VAE 解码按帧走数据并行轴，两者布局不同。若不做处理，阶段切换需要在设备间做一次全量 latent 重排：把按序列块切分的 latent 重新按帧聚合到负责该帧解码的设备上。重排的字节数是整个 latent 张量，且是一次同步屏障——它不藏在任何计算后面。推导上，重排代价正比于 $\\text{latent 元素数} \\times$ 跨设备跳数，跨节点时直接吃 IB 带宽，并且像素若跨节点传输，量级远大于 latent（像素是解码后的高分辨率输出），这是必须避免的。</p>\n<p>机制上的解法是用 JAX sharding annotation 统一声明两阶段的布局，让编译期把重排与相邻通信融合：采样结束时 latent 的序列分片布局与 VAE 所需的帧布局之间的置换，被编译成一次带约束的 collective，而不是运行期的显式拷贝循环。伪代码思路是给采样输出与 VAE 输入打上同一组 `PartitionSpec`，把序列轴上的帧块映射到数据并行轴的设备编号，使\"帧 $f$ 的解码落在持有帧 $f$ latent 的设备上\"成为编译期可验证的约束，从而消除跨节点像素搬运。</p>\n<p>代价是编译复杂度：布局不一致时融合失败会退化为运行期全量重排，latent 在设备间反复搬运，显存与同步开销陡增，这是列出的失败模式之一。工程判断是：宁可让 VAE 的数据并行轴与采样序列轴的设备分组在物理上重合（同一组卡既做序列分片又做帧解码），也不要为了拓扑整齐而引入一次跨节点置换。具体例子：多节点集群里，若把 VAE 解码集中到另一组节点，则每个采样步结束都要把整段 latent 推过 IB，端到端时延被这次搬运主导；让解码留在原节点、只在本节点内做帧重排，代价降为节点内 NVLink 置换。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-18\">十八 · 分片上限、批上限与重编译的联合约束</h3>\n<p>把上面的公式收束成可执行的容量约束，需要同时满足三条不等式：每卡序列分片显存（含 KV 缓冲与通信缓冲）不超过 HBM 预算；$\\text{Comm}$ 项不超过第一项的某个比例阈值（否则加卡亏损）；批大小不超过触发重编译的边界。第三条最容易被忽略——动态 batch 与变长请求会改变 sharding 的形状，JAX 在形状变化时重新编译，编译缓存未命中时首帧时延出现尖峰，流式 SLO 在负载波动下守不住。</p>\n<p>可实现的折中是：按序列长度设分片上限（固定 $P_s$ 与每片最大 token 数），把批维度做成静态上界加 mask，使编译图在批上界内复用；对超长请求走独立的分片档位而非动态伸缩。系统代价是显存按批上界预留、吞吐在低负载时无法拉满，但换来的是时延方差可控。具体例子：固定步数的高分辨率视频生成，请求形态稳定，把批上界设成通信缓冲能容纳的最大值、序列分片按帧块对齐，编译一次后整批请求共享同一执行图，首帧时延不再随负载抖动；反之若允许批动态变化，每次批变化都触发一次布局重推，尖峰出现在最不该出现的首帧。</p>\n<p>最后落到一个具体机制上：把 $\\text{Comm}_{\\text{attn}}$ 的比例阈值写进调度器的准入判断——当某请求的序列长度使 $N/P_s \\cdot d \\cdot N_h$ 超过当前拓扑下单步计算量的设定比例时，拒绝增大 $P_s$ 而改用时间分块（见分块重叠那条线），而不是继续加卡。这条判断把公式从纸面变成准入策略，也是这套并行方案与朴素张量并行真正的分野所在。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-19\">十九 · 边界：通信项何时吃掉整条流水线</h3>\n<p>把 $T_{\\text{step}}$ 的两项拆开看，第一项是算力下界，第二项是搬运下界。序列并行只改变第二项中的 $\\text{Comm}_{\\text{attn}}$，而这一项与序列切分数 $P_s$ 成正比、与头维度 $d$ 和头数 $N_h$ 成正比。关键推导一步在于：每个设备本地只持有 $N/P_s$ 个 token 的 Q，但注意力需要全局 K/V，因此每步必须把本地 KV 块广播给所有 $P_s$ 个设备，单设备出口字节量约为 $\\frac{N}{P_s}dN_h$ 乘以交换轮数，ring 实现下轮数为 $P_s-1$，all-gather 下等价于一次全量汇聚。于是当 $N$ 随分辨率与时长线性增长时，通信项的增长速度与算力项（正比于 $N^2$ 的注意力 FLOPs 除以 $P\\cdot\\text{TC}$）并不同阶，存在一个交叉点：超过它之后，增大 $P_s$ 只是把算力项压下去，却把通信项抬上来，端到端时延不再下降。这个交叉点由跨节点互联带宽决定，而不是由卡数决定。</p>\n<p>失效条件可以写成一条工程判据：若 $\\frac{\\text{Comm}}{\\text{NVLink}}$ 已经接近甚至超过 $\\frac{\\text{Bytes}}{\\text{BW}}$，说明重叠窗口被填满，WGMMA 与 NVLink 传输无法再互相掩盖，此时继续加序列并行轴只会拉长时延。典型场景是跨节点部署：节点内 NVLink 5 带宽充裕，序列切分放在节点内尚可；一旦 $P_s$ 跨出节点边界，KV 交换落到 IB 上，单步时延立刻被互联带宽钉住。伪代码层面的判断很直接——在布局注解阶段就应约束 $P_s$ 不超过单节点设备数，跨节点只允许张量并行轴或数据并行轴伸展，把序列切分锁在 NVLink 域内。</p>\n<table class=\"mini\"><thead><tr><th>切分位置</th><th>通信载体</th><th>对 $T_{\\text{step}}$ 的影响</th><th>适用条件</th></tr></thead><tbody><tr><td>节点内序列并行</td><td>NVLink</td><td>可被 WGMMA 重叠掩盖</td><td>长序列、单节点可容纳分片</td></tr><tr><td>跨节点序列并行</td><td>IB</td><td>成为时延下限</td><td>仅当算力项远大于通信项</td></tr><tr><td>跨节点张量并行</td><td>IB</td><td>all-reduce 频次高、粒度小</td><td>权重放不下时的兜底</td></tr></tbody></table>\n<p>第二类失效来自布局不一致导致的编译期融合失败。采样阶段 latent 按序列轴切分，VAE 解码按帧走数据并行轴，若两阶段的 sharding annotation 没有在编译期被识别为可融合的重排，运行期就会退化为全量 latent 搬运：每个设备把不属于自己的帧块发给对应设备，显存峰值与同步开销同时抬升。这一代价不出现在稳态吞吐上，而是出现在阶段切换的那一拍，对以端到端时延为 SLO 的固定步数视频生成尤其致命。规避手段是在统一布局里让帧维与序列维的映射关系在编译期静态可知，把重排表达为一次可融合的 collective，而不是运行期的动态索引。</p>\n<p>第三类代价是编译可行性本身。动态 batch 与变长请求会改变分片形状，触发重编译；编译缓存未命中时首帧时延出现尖峰，流式 SLO 在负载波动下失守。折中办法是设分片上限并对序列长度做桶化，把形状空间压到有限组合，用少量 padding 换取编译缓存命中率。这也解释了适用边界：小模型或短序列下，并行通信开销超过收益，序列并行不应开启；收益随分辨率与序列长度增大而显现，但规模上限始终由跨节点互联带宽与编译可行性共同封顶，而非由可用卡数封顶。</p>\n<h3 id=\"alg-jax-mesh-parallel-video-sec-20\">二十 · 请求形态：什么样的负载才吃得到序列并行的收益</h3>\n<p>网格并行视频推理的负载配方不是一组可以随手调的超参，而是请求形态与并行拓扑之间的一次匹配。序列并行把 latent 序列按帧或空间块切到 mesh 的序列并行轴，收益的前提是每卡分片仍然足够大、大到 WGMMA 的 tile 利用率不塌，同时又足够小、小到单卡显存放得下激活与注意力窗口。这两个约束把可服务的请求形态夹在一个不宽的区间里：高分辨率、长时长、固定采样步数的生成请求落在这个区间中央；短序列、低分辨率、变长交互式请求落在区间边缘甚至外面。</p>\n<p>用公式看更直接。单步时延由计算项与带宽项取大：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right),\\quad \\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</div>\n<p>其中 $P$ 是参与计算的设备数，$P_s$ 是序列并行轴的大小，$N$ 是序列长度，$d$ 是头维度，$N_h$ 是头数。第一项随 $P$ 增大而下降，第二项里的 $\\text{Comm}_{\\text{attn}}$ 却随 $N/P_s$ 增长——切分越多，每卡本地序列越短，但需要交换的 KV 总量并不因此减少，反而因为参与交换的设备变多、跨节点跳数增加而抬高有效通信代价。这就是负载配方的核心张力：加卡能摊薄 FLOPs，却摊不薄 KV 交换的绝对字节数。</p>\n<p>因此一个合格的负载配方要同时回答三件事：序列长度落在哪个量级、批大小取多少、并发请求的形态是否同质。举例来说，一批 720p、数秒时长、固定步数的生成请求，latent 序列长且各请求长度接近，序列并行轴取 4 到 8、张量并行轴取 2，每卡分片仍能喂饱 tensor core，注意力 KV 交换在单节点 NVLink 域内完成，通信项被 WGMMA 重叠吸收——这是配方最舒服的位置。反过来，一批长度参差、分辨率混杂的请求，切分方案无法统一，布局在编译期无法融合，收益立刻转向代价。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-21\">二十一 · 长度分布：切分上限由最长序列而非平均长度决定</h3>\n<p>长度分布对这套机制的影响不是线性的，而是由分布的长尾决定的。序列并行轴的大小 $P_s$ 一旦选定，每卡分片长度约为 $N/P_s$；为了让同一编译产物服务整批请求，$P_s$ 必须按批内最长序列来定，否则最长的那条会溢出分片显存或触发重编译。这意味着平均长度短、长尾长的分布会浪费大量算力：绝大多数请求的分片远小于 tensor core 的经济粒度，计算项 $\\text{FLOPs}/(P\\cdot\\text{TC})$ 被拉高，而通信项并未同比下降。</p>\n<p>注意力本身在切分后仍是局部计算：</p>\n<div class=\"formula\">$$\\text{Attn}(Q,K,V)=\\text{softmax}\\left(\\frac{QK^{\\top}}{\\sqrt{d}}\\right)V$$</div>\n<p>$Q,K,V$ 按序列轴切到各设备，$K,V$ 经 ring 或 all-gather 在设备间交换后本地计算局部注意力块。注意这里的代价结构：ring 交换的轮数正比于 $P_s$，每轮搬运的字节正比于本地分片的 $d\\cdot N_h$。当 $N$ 增长而 $P_s$ 不变，每卡分片变长、本地计算变重，通信占比反而下降；当 $N$ 不变而 $P_s$ 增大，通信轮数上升、单轮字节下降，总通信量大致守恒但延迟被切得更碎，重叠窗口变窄。所以长度分布的正确用法是：让 $P_s$ 随 $N$ 档位分桶，而不是让一个 $P_s$ 通吃。</p>\n<p>工程上的判断标准是分片下限。设每卡分片长度低于某个阈值时 WGMMA 的 K 维累加效率明显下滑，则 $P_s \\le N/N_{\\min}$ 就是硬上限；同时跨节点场景下 $P_s$ 超过单节点 GPU 数会把 ring 交换推到 IB 上，$\\text{Comm}_{\\text{NVLink}}$ 项里的有效带宽骤降，时延下限被互联带宽锁死。一个具体例子：单节点 8 卡、NVLink 域内做 $P_s=8$ 的 ring 交换是划算的；一旦 $P_s=16$ 跨两个节点，注意力 KV 交换有一半走 IB，端到端时延不再随加卡下降，反而因为同步点增多而抖动。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-22\">二十二 · 并发与批大小：批是通信缓冲的乘数</h3>\n<p>批大小在这套机制里不是吞吐旋钮，而是显存与通信缓冲的乘数。每卡的显存占用大致由三块构成：权重分片、本地 latent 分片激活、以及为 all-gather/ring 准备的 KV 通信缓冲。第三块正比于批大小乘以分片长度乘以 $d\\cdot N_h$，且必须在通信开始前就位，无法像激活那样随计算推进逐块释放。因此批大小的上限往往先被通信缓冲撞到，而不是被激活撞到。</p>\n<p>这带来一个反直觉的结论：序列并行度越高，可用的批大小越小。因为 $P_s$ 增大后每卡分片变短，单请求的通信缓冲变小，但 ring 交换的轮数变多、每轮需要驻留的缓冲份数变多，净效果是缓冲总量对批大小更敏感。实践中常见的配方是固定总 token 预算——批大小乘以序列长度近似恒定——然后在这个预算下调整 $P_s$，让每卡分片落在 tensor core 的经济区间。吞吐随批大小上升而上升，但一旦跨过缓冲上限，调度器要么拒绝请求、要么降批，后者会造成 GPU 利用率出现台阶式下跌。</p>\n<p>并发请求的同质性同样关键。JAX 的 sharding annotation 在编译期决定布局，同一编译产物要求批内所有请求共享同一套切分方案。若并发请求的分辨率或时长不一致，要么按最长者补齐（浪费算力），要么分桶编译（增加编译缓存条目）。流式场景下请求持续到达、长度动态变化，分桶边界一旦设得太细，编译缓存命中率下降，首帧时延出现尖峰；设得太粗，补齐浪费吃掉并行收益。这条折中线的位置取决于编译缓存的容量与预热策略，而不是单纯的并行度调优。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-23\">二十三 · 负载不对时的三种塌陷</h3>\n<p>第一种塌陷是通信压垮带宽。序列切分过多时，注意力 KV 的 all-gather 或 ring 交换通信量随序列长度增长，跨节点 IB 带宽成为瓶颈，WGMMA 与 NVLink 通信的重叠不足以掩盖时延。表现是加卡不加速：$P$ 翻倍后计算项减半，但通信项因跨节点跳数增加而上升，$T_{\\text{step}}$ 的 max 取到通信侧，端到端时延持平甚至变差。诊断方法是看单步时间里通信等待的占比是否随 $P_s$ 单调上升。</p>\n<p>第二种塌陷是布局不一致导致运行期重排。采样阶段用序列并行轴、VAE 解码用数据并行轴，两者靠 sharding annotation 在编译期融合重排；一旦布局在阶段间不一致且融合失败，就退化为运行期全量重排，latent 在设备间反复搬运，显存与同步开销陡增。这种失败不会报错，只会让端到端时延比预期高出一截，且随批大小放大。它对应的工程动作是：把采样与 VAE 的布局声明写在同一处、用同一套 mesh 轴命名，并在编译产物里检查重排是否被融合掉。</p>\n<p>第三种塌陷是重编译尖峰。动态 batch 与变长请求触发频繁重编译，编译缓存未命中时首帧时延出现尖峰，流式 SLO 在负载波动下难以守住。这类失败的代价不在稳态吞吐，而在尾延迟：稳态下一切正常，一旦请求形态跳变，调度器被迫为新形状编译，期间 GPU 空转。缓解手段是预热常见形状、给批大小与序列长度设离散档位、并在准入控制里拒绝落在档位之间的请求，而不是让编译器去追任意形状。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-24\">二十四 · 配方与 SLO 的对应：把时延下限算清楚再定并行度</h3>\n<p>负载配方的最终形态是一张把请求形态映射到并行拓扑与批上限的表。SLO 以端到端时延为主时，配方要保证 $T_{\\text{step}}$ 的 max 落在计算侧而非通信侧，也就是让 $\\text{FLOPs}/(P\\cdot\\text{TC})$ 大于 $\\text{Bytes}/\\text{BW}+\\text{Comm}/\\text{NVLink}$，并留出重叠吸收的余量。跨节点时 NVLink/IB 带宽是时延下限，任何并行度提升都不能突破这个下限，因此配方里必须显式标注\"单节点内可加卡、跨节点只加批\"的边界。</p>\n<p>具体做法是按序列长度分档给出 $(P_s, P_t, B)$ 三元组：短序列档用小 $P_s$、大 $B$，把并行度让给批吞吐；长序列档用大 $P_s$、小 $B$，把显存让给分片；跨节点档固定 $P_s$ 不超过单节点 GPU 数，靠增加数据并行副本吃并发。每档对应一个编译产物，档位之间的请求在准入层被归并或拒绝。量化（FP8/NVFP4）降低分片激活与权重占用，等价于把每档的 $B$ 上限抬高，但它不改变通信项的字节数，所以不能用来救通信塌陷。</p>\n<p>KV 按序列分片本地持有、跨块或跨请求不共享，这一点直接约束配方：批内请求不能靠共享 KV 来摊薄通信，每个请求的 KV 交换独立计费。于是批大小的经济性来自计算侧的摊薄，而不是通信侧的复用。把这条记进配方表，就能避免\"加大批大小以摊薄通信\"这种在别的并行范式里成立、在这里不成立的直觉。</p>\n<p>最后落在机制上：配方表的每一档都对应一次编译期的布局决策，而布局决策的代价是编译时间与缓存容量。序列长度档位越细，命中率越高但缓存条目越多；档位越粗，补齐浪费越大。这条折中线的位置由编译缓存容量、预热请求集合与 SLO 尾延迟预算三者共同决定，调参的抓手是档位边界而不是并行度本身——并行度已经被互联带宽和分片下限锁死，剩下的自由度只在档位划分上。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-25\">二十五 · 负载配方：长序列固定步数才是它的舒适区</h3>\n<p>这套网格并行的收益结构由 <span class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right),\\quad \\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</span> 决定：当序列长度 N 足够大、单卡放不下 latent 时，第二项被序列并行摊薄，计算项成为主项，多卡才真正划算。因此理想请求形态是高分辨率、长时长、固定去噪步数的批量视频生成——步数固定意味着计算图稳定，sharding annotation 一次编译即可复用，批大小则由每卡序列分片显存与通信缓冲共同约束，而不是由权重显存约束。反过来说，短序列、小分辨率、单卡即可容纳的请求，序列并行轴上的 all-gather 与 ring 交换纯属额外开销，收益为负。SLO 也应以端到端时延为主而非吞吐，因为跨节点 NVLink/IB 带宽直接构成时延下限。</p>\n<p>负载一旦偏离配方，失效是分层的。第一层是切分过细：序列切分数 P_s 增大使每卡分片变小，但 KV 的 ring/all-gather 通信量随 N 增长，跨节点 IB 带宽成为瓶颈，WGMMA 与通信的重叠不足以掩盖，此时增加卡数反而拉长单步时延。第二层是布局不一致：采样阶段按序列轴切分、VAE 解码按帧走数据并行轴，若 sharding annotation 未统一，编译期融合失败会退化为运行期全量重排，latent 在设备间反复搬运，显存与同步开销陡增。第三层是动态性：变长请求与动态 batch 触发频繁重编译，编译缓存未命中时首帧时延出现尖峰，流式 SLO 在负载波动下守不住。</p>\n<p>工程上的判断标准可以写成一张粗略的配方表：</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>适配度</th><th>主导代价</th></tr></thead><tbody><tr><td>高分辨率长视频、固定步数、批上限内</td><td>适配</td><td>跨节点互联带宽构成时延下限</td></tr><tr><td>短序列、单卡可容纳</td><td>不适配</td><td>通信开销超过并行收益</td></tr><tr><td>变长、动态 batch、突发流式</td><td>需折中</td><td>重编译尖峰与缓存命中率</td></tr></tbody></table>\n<p>因此部署时应按序列长度设分片上限，把批大小压在编译缓存可覆盖的离散档位上，并用 FP8/NVFP4 降低分片激活与权重占用以换取更大的批上限；KV 按序列分片本地持有、跨块不共享，避免 all-gather 规模随请求数膨胀。若业务以短请求为主，应把序列并行轴收缩到单节点内，让跨节点只承担数据并行，而不是硬套多节点序列切分。</p>\n<h3 id=\"alg-jax-mesh-parallel-video-sec-26\">二十六 · 硬件档位：从单节点八卡到多节点 NVL72 的分档判据</h3>\n<p>部署配方的第一刀不是选框架，而是定档位。判据只有一条：单卡能否同时容纳一份 latent 分片、一份权重分片和一份注意力 KV 工作集。以高分辨率长视频 DiT 为例，权重按张量并行切到 $P_t$ 卡后每卡权重占用近似 $W/P_t$（$W$ 为总参数量对应字节数），而序列并行轴 $P_s$ 上每卡持有的 KV 工作集近似正比于 $N/P_s \\cdot d \\cdot N_h \\cdot L$（$N$ 为 latent 序列长度，$L$ 为层数）。两条约束同时成立才谈得上单节点：</p>\n<div class=\"formula\">$$\\frac{W}{P_t}+\\frac{N\\,d\\,N_h\\,L\\,b_{\\text{kv}}}{P_s}\\le C_{\\text{HBM}},\\qquad P_t\\cdot P_s\\le 8$$</div>\n<p>单节点八卡（B200/GB200 单机内 NVLink 5 全互联）是首选档位，因为 $P_t\\cdot P_s\\le 8$ 时所有通信落在 NVLink 域内，不经过 IB。当 $N$ 增长到单节点放不下，或 $P_s$ 需要超过 8 才能把每卡 KV 压进 HBM，就必须升到多节点 GB200/GB300 NVL72：此时 NVLink 域扩展到 72 卡，序列并行轴可以跨机柜展开而仍走 NVLink，只有超出 72 卡的规模才真正落到 IB 上。工程判断是：**优先把 $P_s$ 扩到 NVL72 域内上限，再考虑跨 IB**，因为跨 IB 的 ring 交换会把 $T_{\\text{step}}$ 的第二项直接顶起来。一个具体例子：某 1080p、数十秒时长的 DiT 采样，若每卡 KV 工作集在 $P_s=8$ 时仍超出 HBM 余量，则升到 NVL72 内 $P_s=16$ 或 $P_s=32$，通信仍在 NVLink 域，时延下限不变；若强行留在八卡而减小分片，注意力窗口被切碎，重排与 halo 开销反而上升。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-27\">二十七 · 并行拓扑：序列轴乘张量轴的二维 mesh 与 VAE 数据并行轴</h3>\n<p>拓扑不是“多切几刀”，而是把三个语义不同的轴映射到物理 mesh 上。采样阶段用二维 mesh：序列并行轴 $P_s$ 切 latent 的帧/空间块，张量并行轴 $P_t$ 切注意力头与 FFN 通道。注意力阶段每卡本地算 $QK^{\\top}$，$K,V$ 通过 ring 或 all-gather 在 $P_s$ 轴内交换，通信量按给定事实正比于 $N/P_s \\cdot d \\cdot N_h$；FFN 阶段本地 GEMM 后在 $P_t$ 轴做 all-reduce，残差本地累加。关键在于两个轴的通信原语不同：$P_s$ 轴是带宽密集的 KV 交换，$P_t$ 轴是低延迟的 all-reduce，把它们放在同一 mesh 的不同维度上，才能让 WGMMA 与 NVLink 传输重叠而不互相阻塞。</p>\n<p>VAE 解码阶段换轴：latent 按帧重排到数据并行轴，每卡独立解码自己那几帧，像素不出节点。这一步的代价是阶段间一次 latent 重排——若用 sharding annotation 在编译期把重排融合进布局变换，重排是设备内或 NVLink 域内的块拷贝；若布局不一致导致编译期融合失败，就退化为运行期全量重排，latent 在设备间反复搬运，显存与同步开销陡增（这正是给定失败模式之一）。伪代码思路：</p>\n<ul>\n<li>采样：<code>latent = shard(latent, axis=(\"frame_block\",\"sp\"))</code>，权重 <code>shard(W, axis=(\"head\",\"tp\"))</code>；</li>\n<li>注意力：本地 QKV → ring/all-gather KV → 本地 softmax 块；</li>\n<li>FFN：本地 GEMM → all-reduce(tp) → 本地残差；</li>\n<li>VAE：<code>latent = reshard(latent, axis=(\"frame\",\"dp\"))</code>，逐帧解码。</li>\n</ul>\n<p>系统代价上，$P_s$ 越大单卡计算越少但 KV 交换越多；$P_t$ 越大 all-reduce 越频繁。给定公式 $T_{\\text{step}}\\approx \\max(\\text{FLOPs}/(P\\cdot\\text{TC}),\\ \\text{Bytes}/\\text{BW}+\\text{Comm}/\\text{NVLink})$ 说明：当 $\\text{Comm}$ 项超过计算项，加卡不再降时延。因此拓扑选择是让两项大致平衡，而不是把 $P$ 堆到最大。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-28\">二十八 · 量化方案：分片激活与权重的精度分配</h3>\n<p>量化在本配方里的角色是“把分片压进 HBM 并抬高 TC 利用率”，而不是单独追求最低位宽。权重走 FP8 或 NVFP4 存在 $P_t$ 轴的分片上，激活的分片同样量化，使每卡 HBM 占用按位宽比例下降，直接放宽第一节的容量不等式，让更小的 $P_s$ 也能成立——这等价于把通信量按 $N/P_s$ 压下来。精度分配的工程规则：注意力 $QK^{\\top}$ 的 softmax 输入对量化误差敏感，$Q,K$ 保持较高精度或做 per-block 缩放；$V$ 与 FFN 激活可用 NVFP4 配合块级 scale；残差累加保持高精度本地进行，避免 all-reduce 前后累积误差。</p>\n<p>代价有两面。其一，量化降低 $\\text{Bytes}$ 项（权重与激活搬运），但若 KV 也量化，ring 交换的字节数下降、$\\text{Comm}$ 项同步下降，这是序列并行下量化的额外收益；其二，低精度 GEMM 在 tcgen05/TMEM 路径上要求布局对齐，分片边界若与量化块边界不齐，会引入额外的重排或 padding，抵消部分收益。具体例子：同一长视频采样，权重 FP8 使每卡权重占用减半，$P_t$ 可从 4 降到 2，把省下的卡挪给 $P_s$，KV 交换的每卡负担下降而总通信拓扑不变；若进一步把 $V$ 与 FFN 激活降到 NVFP4，$\\text{Bytes}$ 项继续下降，$T_{\\text{step}}$ 的带宽分支被压低，但需确认分块边界与量化块对齐，否则重排开销吃掉收益。量化方案必须与拓扑联合选，不能先定量化再定 mesh。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-29\">二十九 · KV 策略：按序列分片本地持有，拒绝跨请求共享</h3>\n<p>视频 DiT 的 KV 策略与语言模型不同：这里没有跨请求复用的前缀缓存语义，KV 是采样过程中注意力窗口的工作集。给定事实明确要求“KV 按序列分片本地持有，跨块或跨请求不共享，避免 all-gather 规模膨胀”。机制上，每卡只持有自己 $P_s$ 分片对应的 $K,V$ 块，注意力计算时通过 ring 逐跳传递邻居块或 all-gather 拼接，计算完即释放，不进入任何全局池。这样 KV 的显存占用被 $P_s$ 严格约束，且 all-gather 的规模只与当前步的窗口有关，不随并发请求数累积。</p>\n<p>为什么不能共享：若把多请求的 KV 汇入共享池，all-gather 的字节数随并发数线性增长，$\\text{Comm}$ 项直接压垮跨节点带宽，且分片布局被并发打乱，触发重编译。KV 策略还要与序列长度上限联动：按序列长度设分片上限，超过上限的请求要么拒绝、要么走分块重叠路径（那是相邻条目的主题，此处只指路）。代价是显存利用率不如共享池“看起来”高，但换来的是通信可预测、编译布局稳定。具体例子：固定批大小下，每卡 KV 工作集由 $N/P_s$ 决定，若把批从 1 提到 2 而不加卡，KV 翻倍可能越界，正确做法是提高 $P_s$ 或降低分辨率，而不是把两份 KV 塞进共享池让 all-gather 翻倍。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-30\">三十 · 调度参数：批上限、编译缓存与分片上限的三角折中</h3>\n<p>调度参数在 JAX 静态形状体系下不是连续旋钮，而是离散的编译单元。给定事实指出动态 batch 与变长请求会触发重编译，编译缓存未命中时首帧时延出现尖峰。因此调度配方要显式定义三个参数：批上限 $B_{\\max}$、序列分片上限 $S_{\\max}$、编译缓存条目数。$B_{\\max}$ 由每卡序列分片显存与通信缓冲共同约束（第一节的不等式在 $B$ 倍下仍成立）；$S_{\\max}$ 决定 $P_s$ 的离散档位集合，请求按序列长度向上取整到最近的档位，牺牲少量算力换取编译命中；缓存条目数按“档位 × 批上限”的组合数预留，超出则淘汰最冷组合。</p>\n<p>伪代码思路：请求到达时先算所需 $P_s$ 档位，查缓存；命中则直接进入执行队列，未命中则编译并插入缓存，同时对该档位做预热以摊薄首帧尖峰。SLO 以端到端时延为主时，调度器应优先保证档位命中率而非追求批尽可能大——批越大，$B_{\\max}$ 档位越多，缓存越容易失配。系统代价上，编译缓存占用主机内存与编译时间，档位过细则缓存膨胀、过粗则算力浪费；工程判断是把档位集合控制在个位数，让绝大多数请求落在两三个档位内。具体例子：流式生成场景下请求时长不一，若每个长度都独立编译，首帧时延尖峰在负载波动时无法守住 SLO；改为按帧数分档（如短/中/长三档）后，缓存命中率上升，尖峰被限制在档位切换点。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-31\">三十一 · 可复现的配置思路：从容量不等式反推 mesh</h3>\n<p>把前五节收束成一条可复现的推导链，而不是给一张拍脑袋的参数表。第一步，测出目标分辨率与时长下的 $N$、$d$、$N_h$、$L$ 与权重字节 $W$；第二步，用第一节不等式在候选档位（单节点八卡、NVL72 内 16/32 卡）上求解可行的 $(P_t,P_s)$ 组合，优先让 $P_t\\cdot P_s$ 落在 NVLink 域内；第三步，按第三节选量化方案，用位宽折减重算不等式，看能否把 $P_s$ 降一档以减通信；第四步，按第四节固定 KV 本地持有并设 $S_{\\max}$，按第五节设 $B_{\\max}$ 与缓存档位；第五步，用 $T_{\\text{step}}$ 公式估算每步时延，检查 $\\text{Comm}/\\text{NVLink}$ 项是否已成为主项，若是则回到第二步调整拓扑而非加卡。</p>\n<p>这条链的稳定性技巧直接对应给定事实：用 sharding annotation 统一采样与 VAE 布局以减少阶段间重排、把通信与 WGMMA 重叠、按序列长度设分片上限。失败模式的检查点也内嵌在链里：若 $P_s$ 档位过多导致 KV all-gather 随长度增长压垮跨节点带宽，说明第二步的拓扑选错；若采样与 VAE 布局不一致导致运行期全量重排，说明第一步的 annotation 没统一；若缓存未命中造成首帧尖峰，说明第五步档位过细。最终配置的形态是：一个二维 mesh 的 $(P_t,P_s)$、一套按块对齐的量化精度表、一个本地持有的 KV 分片规则、一组个位数的编译档位——四者互相约束，任何一项单独调优都会被其他三项的代价抵消。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-32\">三十二 · 配方失效的四个断点与代价核算</h3>\n<p>这套配方不是无条件可用的。第一个断点是序列切分粒度与互联带宽的比值：注意力通信量按 <span class=\"formula\">$$\\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</span> 增长，当 <span class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right)$$</span> 的第二项压过第一项时，增加 <span class=\"formula\">$$P_s$$</span> 不再缩短步时延，反而抬高跨节点 IB 占用。工程判断是：先按单节点 NVLink 域内可容纳的最大序列分片数定 <span class=\"formula\">$$P_s$$</span>，跨节点只在显存确实不够时启用，并把 ring 交换限制在节点内、节点间只做必要的 KV 全收集。</p>\n<p>第二个断点是布局一致性。采样阶段 latent 切在序列并行轴、VAE 解码切在数据并行轴，两者靠 sharding annotation 在编译期融合重排；一旦动态 shape 使融合失败，退化为运行期全量重排，latent 在设备间反复搬运，显存峰值与同步开销同时抬升。可复现的做法是把批上限与分辨率档位做成有限枚举，让编译缓存命中率可预期，用少量首帧时延尖峰换取稳态可守的 SLO。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>直接代价</th><th>配方侧应对</th></tr></thead><tbody><tr><td>序列切分过多</td><td>IB 带宽成为时延下限，重叠不足以掩盖</td><td>设分片上限，优先节点内切分</td></tr><tr><td>采样与 VAE 布局不一致</td><td>运行期全量重排，显存与同步陡增</td><td>统一 annotation，枚举 shape</td></tr><tr><td>变长请求频繁重编译</td><td>首帧时延尖峰，流式 SLO 失守</td><td>编译缓存加批上限折中</td></tr></tbody></table>\n<p>第三个断点是 KV 策略的边界：KV 按序列分片本地持有、跨块跨请求不共享，这避免了 all-gather 规模膨胀，但也意味着固定步数生成下每卡通信缓冲随分片长度线性占用显存，批大小实际由“分片激活 + 通信缓冲”共同封顶，而非仅由权重决定。量化用 FP8/NVFP4 压缩分片激活与权重能腾出缓冲空间，但低精度下注意力 softmax 的数值敏感度要求对 QK 乘积保留更高精度路径。第四个断点是小规模场景：短序列、小模型下并行通信开销超过收益，此时应退回单卡或纯张量并行，配方中的序列并行轴取 1。收益随分辨率与时长增大而显现，规模上限则由跨节点互联带宽与编译可行性共同决定，机制线可对照 paper-vidax-a-unified-jax-framework-for-vi-2026 与 paper-ultra-flash-scaling-real-time-stream-2026。</p>\n<h3 id=\"alg-jax-mesh-parallel-video-sec-33\">三十三 · 从 roofline 到 mesh roofline：代价函数的形状变了</h3>\n<p>单卡推理的代价判断只需一个 roofline：每步时间取计算与访存的上界。到了序列并行加张量并行的 mesh 上，这个上界要再叠一层通信项，并且通信项不是常数，而是随序列切分数与跨节点拓扑变化的函数。本片段采用的判据是：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right),\\quad \\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</div>\n<p>这里 $P$ 是参与该步的设备总数，$P_s$ 是序列并行轴的度数，$N$ 是 latent 序列长度，$d$ 为头维度，$N_h$ 为头数。注意第二项的结构：访存项与通信项是相加而非取 max，因为本地 HBM 读写与 NVLink 交换在同一段流水里争用同一批 SM 的发射槽与 L2 通路，二者难以完全重叠。这决定了规模上去以后第一个崩的往往不是 FLOPs 项——Blackwell 的 tcgen05 MMA 在 FP8/NVFP4 下把计算项压得很低——而是第二项里随 $N/P_s$ 线性增长的通信量。当 $P_s$ 增大，$N/P_s$ 下降，但每增加一档 $P_s$ 就多一次跨设备交换，且交换的对端从节点内 NVLink 5 域扩到节点间 IB 域，带宽量级骤降。于是存在一个拐点：继续加卡使计算项继续变小，通信项却因跨域而反超。这个拐点的位置由互联拓扑而非 SM 数量决定，是容量规划里必须先算清的量。</p>\n<p>具体例子：一条高分辨率长视频的 latent 序列在单节点 8 卡内按 $P_s=8$ 切分时，注意力 KV 交换全部落在 NVLink 5 域内，通信项被 WGMMA 的异步执行掩盖；把 $P_s$ 提到 16 跨两节点，交换的一半流量走 IB，即便计算项因设备翻倍而减半，端到端步时也可能不降反升。工程判断是：先测单节点内 $P_s$ 饱和点，再决定是否跨节点，而不是按“卡越多越快”线性外推。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-34\">三十四 · 显存：分片把峰值搬到通信缓冲上</h3>\n<p>序列并行确实把 latent 激活与注意力窗口摊到了多卡，单卡激活峰值约按 $P_s$ 缩小。但显存账本不是只有激活一项。每张卡还要持有：本地的 K/V 分片、为 all-gather 或 ring 交换准备的接收缓冲、FFN all-reduce 的暂存、以及 JAX 编译产生的常量与布局元数据。接收缓冲的尺寸与交换粒度直接相关——ring 交换可以只缓冲一个时隙的 KV 块，all-gather 则要一次性容纳全部对端的 KV，后者的峰值随 $P_s$ 线性上升。于是出现一个反直觉现象：把 $P_s$ 从 8 提到 16，激活峰值减半，但 all-gather 缓冲翻倍，净显存收益被吃掉大半。批大小因此不是由激活单独约束，而是由“激活 + 最大通信缓冲”共同约束，这正是负载配方里批上限受通信缓冲约束的物理来源。</p>\n<p>另一个隐性占用来自阶段切换。采样阶段按序列并行轴布局，VAE 解码按帧走数据并行轴；若 sharding annotation 在两侧不一致，编译期融合失败，运行期就要把 latent 全量重排，重排期间源布局与目标布局的缓冲同时驻留，显存瞬时抬升。这不是容量问题而是峰值问题，恰恰最容易在长视频上触发 OOM。工程做法是把两阶段的布局在编译期对齐到同一 mesh 切分，让重排退化为元数据改写而非数据搬运；代价是布局自由度受限，某些为 VAE 帧并行专门优化的切法要让步。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-35\">三十五 · 带宽：HBM 与互联是两条不同的紧约束</h3>\n<p>公式第二项里的 Bytes/BW 是本地 HBM 项，Comm/NVLink 是互联项，二者量级不同、随规模变化的方向也不同。HBM 项随 $P_s$ 增大而按分片缩小，因为每卡只读写自己的那一段；互联项则随交换次数与对端数量增长。规模上去后，两条曲线的交叉点就是“本地带宽不再是瓶颈、互联成为瓶颈”的分界。Blackwell 节点内 NVLink 5 域带宽充裕，使得 $P_s$ 在节点内扩张时互联项仍可被掩盖；一旦跨节点走 IB，互联项的量级跳变，掩盖能力消失。此时继续增大 $P_s$ 只增加交换跳数与对端数，Comm 项里的 $N/P_s$ 虽降，但每次交换的固定开销与跨域延迟摊不薄。</p>\n<p>注意力交换的形态选择因此是带宽账本的关键。ring 交换把 KV 沿环逐跳传递，单卡瞬时带宽需求低、可与时隙内的 WGMMA 重叠，适合节点内大 $P_s$；all-gather 一次性拉齐全部 KV，延迟低但瞬时带宽峰值高，跨节点时容易打满 IB。工程上常见的是分层混合：节点内 ring、节点间 all-gather 或分层 reduce，让跨节点流量只发生在聚合后的少量大块上。伪代码思路是：本地算完 QKV 后，先在节点内 ring 一圈补齐节点内 KV，再把节点级聚合块经 IB 广播到其他节点，最后本地计算局部注意力块。这样跨节点流量与节点数成正比而与 $P_s$ 无直接线性关系，是抑制通信项随规模爆炸的主要手段。</p>\n<p>具体代价：长视频序列长度翻倍时，若 $P_s$ 不变，注意力交换量按 $\\text{Comm}_{\\text{attn}}\\propto N/P_s$ 翻倍；若同步把 $P_s$ 翻倍，交换量持平但跨节点跳数增加，端到端时延的下限由 IB 往返延迟而非带宽决定。这就是为什么长视频扩容不能只靠加 $P_s$，还要靠分层聚合把跨域流量压到聚合块级别。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-36\">三十六 · 功耗与热：并行不降低总能量，只改变分布</h3>\n<p>多卡并行把单卡的计算时间缩短，但设备数增加，总算力功耗并不按比例下降——空闲等待通信的卡仍在漏电与维持时钟。序列并行下每卡的 MMA 占空比取决于通信掩盖效率：掩盖得好，SM 持续发射，功耗接近计算满载；掩盖不好，SM 在等 NVLink 时反复进出低功耗态，功耗曲线呈锯齿，热设计反而更难。跨节点场景里，IB 网卡与交换机的功耗进入集群预算，这部分不体现在单卡 TDP 上，却直接约束机柜功率密度与可部署的 $P_s$ 上限。</p>\n<p>工程判断是把“通信掩盖率”当作功耗与吞吐的共同指标：掩盖率低意味着同一段墙钟时间里既浪费了算力又浪费了电。提高掩盖率的做法是把交换切得更细、更早发起——在 QKV 本地计算尚未完成时就启动第一段 KV 的 ring 传递，让 WGMMA 与 NVLink 传输在同一 warpgroup 调度下交错。代价是缓冲管理更复杂、寄存器压力上升，需要在编译期由布局注解保证切分粒度与流水深度匹配。功耗账本上还有一个易忽略项：VAE 解码阶段走数据并行轴，各卡负载可能不均，帧数不能被设备数整除时出现长短尾，短尾卡提前空闲，整机功耗下降但时延由最长尾卡决定，能效比因此变差。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-37\">三十七 · 尾延迟：重编译与布局失配是尖峰的两个来源</h3>\n<p>吞吐看均值，SLO 看尾延迟。这套 mesh 并行方案里，尾延迟的两个主要来源都不是稳态计算，而是控制面事件。其一是动态 batch 与变长请求触发的重编译：JAX 的编译缓存按形状与布局作键，请求形态一变就命中不了，首帧时延出现尖峰。流式生成的 SLO 恰恰卡在首帧，负载波动下尖峰直接违约。缓解手段是把批上限与序列长度分档离散化，用有限个形状档位覆盖请求分布，让缓存命中率可预期；代价是档位间的形状浪费，短请求被抬到档位下界，算力利用率下降。</p>\n<p>其二是布局失配导致的运行期全量重排。采样与 VAE 的并行轴不同，若编译期未能融合重排，latent 在设备间反复搬运，同步开销陡增，且这种开销随视频长度放大——长视频的 latent 体量大，一次全量重排的搬运量足以让尾延迟翻倍。稳定性技巧里“用 sharding annotation 统一采样与 VAE 布局”正是针对这一点：把重排从数据面搬到元数据面，代价是牺牲部分阶段专属的切分自由度。第三个尾延迟来源是序列切分过多时的交换拥塞：$P_s$ 越大，环上跳数越多，最慢一跳决定整步完成时间，尾延迟对最慢链路的敏感度上升。容量规划上应给 $P_s$ 设上限，并按序列长度分档设定切分数，而不是让切分数随长度线性增长。</p>\n<p>具体例子：一个变长请求流在固定档位下运行平稳，一旦出现超出档位上界的超长视频，触发重编译并伴随一次跨节点全量重排，首帧时延尖峰与后续帧的稳态时延脱节，SLO 监控上表现为孤立的 p99 毛刺而非整体抬升。定位这类问题要看编译缓存命中率与重排搬运量两个指标，而不是只看平均步时。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-38\">三十八 · 规模上限由谁决定：互联与编译可行性</h3>\n<p>把五项代价放在一起，规模上限的判定顺序是清晰的：先看互联。$P_s$ 扩张到跨节点后，Comm 项从可掩盖变为时延下限，此时加卡不再缩短步时，规模收益归零。再看编译可行性。布局注解的组合数随并行轴与阶段数增长，编译时间与缓存占用随之上升，动态请求下重编译频率成为实际约束；当编译缓存无法覆盖请求分布，尾延迟先于吞吐崩掉。显存与功耗是次级约束：显存由激活加通信缓冲共同决定，跨节点时缓冲项主导；功耗由掩盖率与机柜密度决定，跨节点时 IB 设备进入预算。带宽项在节点内不是瓶颈，跨节点时与互联项合并为同一约束。</p>\n<p>因此工程判断应落在“先定互联域、再定 $P_s$ 上限、最后定档位”的顺序上：互联域决定单步时延下限，$P_s$ 上限由该下限与交换跳数的折中点给出，档位由编译缓存可覆盖的请求形状集合给出。序列切分过多使通信成为瓶颈、布局不一致使重排退化、动态请求使重编译尖峰——这三条失败模式恰好对应上述三个判定环节，任何一环失守，规模上去后先崩的都是尾延迟而非均值吞吐。把分层聚合、布局统一、档位离散化三件事在编译期一次做对，比在运行期靠加卡补救更省互联带宽与编译预算。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-39\">三十九 · 规模上去以后，先崩的是跨节点带宽与编译缓存</h3>\n<p>把序列并行轴拉长到多节点时，注意力阶段的 KV 交换量按 <span class=\"formula\">$$\\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</span> 随序列长度 N 线性增长，而每卡只分摊到 <span class=\"formula\">$$N/P_s$$</span> 的本地块。这意味着序列切分越细，单卡计算量下降，但 ring 或 all-gather 的字节数不降反升，一旦跨节点落到 IB 侧，<span class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right)$$</span> 的第二项就压过第一项，WGMMA 与通信的重叠窗口被吃满后，端到端时延直接由互联带宽决定。高分辨率长视频正是最容易踩到这条线的形态：latent 序列长、注意力窗口大，切分数一多，通信缓冲本身也占显存，批大小被迫压到 1，吞吐随卡数增加反而走平甚至回落。</p>\n<p>第二个崩点是阶段间布局不一致。采样阶段按序列并行轴持有 latent，VAE 解码按帧走数据并行轴，若 sharding annotation 未统一，编译期融合失败会退化为运行期全量重排：latent 在设备间反复搬运，像素跨节点传输被引入，显存峰值与同步开销同时抬升。这类退化不报错，只表现为每步时延的隐性抬升，在固定步数配方下被误读为“通信正常”。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先触及的代价</th><th>工程后果</th></tr></thead><tbody><tr><td>序列切分数 P_s 增大</td><td>KV 交换字节数上升，跨节点 IB 带宽</td><td>重叠失效，时延下限由互联决定</td></tr><tr><td>动态 batch / 变长请求</td><td>JAX 重编译，缓存未命中</td><td>首帧时延尖峰，流式 SLO 失守</td></tr><tr><td>阶段布局不一致</td><td>运行期全量重排</td><td>显存与同步开销陡增</td></tr></tbody></table>\n<p>因此规模上限不是由单卡算力给出，而是由“序列切分上限 × 编译缓存命中率”共同约束。工程上应按序列长度设分片上限，把跨节点交换限制在可控字节数内；对变长请求预先枚举批上限与形状桶，让重编译落在缓存里而非请求路径上；FP8/NVFP4 量化降低分片激活占用，为通信缓冲腾出显存。小模型或短序列下，并行通信开销会超过收益，此时退回单节点张量并行或分块重叠更划算。</p>\n<h3 id=\"alg-jax-mesh-parallel-video-sec-40\">四十 · 精度漂移：从分片边界到跨阶段累积</h3>\n<p>网格并行视频推理的精度问题很少来自单点，而是来自“切分”本身。序列并行把 latent 按帧或空间块切到不同设备，注意力局部块在本地 softmax 后再经 ring 或 all-gather 交换 KV，此时每个设备只看到部分序列的归一化统计量；若在 FP8/NVFP4 下把局部 softmax 的缩放因子按本地最大值取，跨块拼接后就会出现块间亮度或运动幅度的不一致，表现为长视频中相邻时空块接缝处的闪烁。张量并行轴上的 all-reduce 又引入一次跨设备累加，残差若在本地先累加再 all-reduce，数值路径与单卡不同，低精度下误差随层数线性放大。</p>\n<p>诊断这类问题不能只看端到端 PSNR，要把误差定位到“哪个轴、哪个阶段”。做法是在采样与 VAE 两个阶段分别插入分片级探针：对每个序列分片记录局部 softmax 分母、FFN all-reduce 前后的激活范数，以及 VAE 按帧数据并行时的逐帧均值。判据是分片间同一统计量的相对偏差，超过阈值即说明该分片的量化缩放或归约顺序与邻居不一致。</p>\n<div class=\"formula\">$$\\epsilon_{\\text{blk}}=\\frac{\\left\\|\\bar{a}_i-\\bar{a}_{i+1}\\right\\|}{\\left\\|\\bar{a}_i\\right\\|},\\quad \\bar{a}_i=\\frac{1}{N_s}\\sum_{j\\in \\text{shard }i} a_j$$</div>\n<p>工程代价上，精度回滚最贵的是“重跑整条链路”：一次采样加 VAE 解码的端到端时延由 <span class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right)$$</span> 决定，跨节点时通信项占比高，回滚意味着重新占用整段 NVLink/IB 带宽。具体例子：当 sharding annotation 在采样阶段把序列切到 8 卡、VAE 阶段按帧切到 4 卡时，若两阶段缩放因子未统一，接缝闪烁只在长视频后段出现，探针需按帧索引而非按请求聚合才能复现。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-41\">四十一 · OOM 的三条来源与显存账</h3>\n<p>OOM 在本算法里通常不是“模型太大”，而是三笔账没算清：序列分片激活、通信缓冲、以及阶段间重排的临时张量。序列并行下每卡持有 <span class=\"formula\">$$N/P_s$$</span> 长度的 latent 分片，注意力窗口内的 K/V 本地持有，跨块不共享；当序列切分数 <span class=\"formula\">$$P_s$$</span> 调大以压时延时，单卡分片变小但 all-gather 缓冲随 <span class=\"formula\">$$\\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</span> 的交换规模并不按同样比例缩小，缓冲反而可能成为峰值。第三笔是 VAE 阶段按帧数据并行时的像素重排：若采样与 VAE 布局不一致，编译期融合失败会退化为运行期全量重排，latent 在设备间反复搬运，显存峰值与同步开销同时抬升。</p>\n<p>监控上不要只报“已用显存”，要按分配器切分三类计数：参数与权重分片、激活分片（含注意力窗口）、通信与重排缓冲。判据是峰值出现在哪一类，以及峰值时刻是否与一次 all-gather 或一次布局重排对齐。回滚手段按代价排序：先降批大小与序列分片上限，再退回 FP8 而非 NVFP4 的激活量化，最后才动并行拓扑。具体例子：多节点集群上把 <span class=\"formula\">$$P_s$$</span> 从 8 提到 16 试图降时延，结果跨节点 all-gather 缓冲翻倍触发 OOM，正确做法是保持 <span class=\"formula\">$$P_s$$</span> 并把张量并行轴加宽，让权重切分吸收显存压力。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-42\">四十二 · 批抖动与重编译尖峰</h3>\n<p>动态 batch 与变长请求是这套 JAX 网格并行的结构性弱点。sharding annotation 在编译期确定布局，批形状或序列长度变化会触发重编译；编译缓存未命中时首帧时延出现尖峰，流式 SLO 在负载波动下守不住。批抖动还有第二层：批内请求的序列长度差异导致分片负载不均，短请求所在分片先完成、长请求分片拖尾，all-gather 必须等最慢分片，形成“批内尾延迟”。</p>\n<p>诊断批抖动要把时延拆成三段：编译等待、分片计算、跨设备同步。监控指标是编译缓存命中率与每批的“最慢分片/平均分片”比值。工程判断是：把批上限与序列长度桶化，用固定形状的编译缓存换掉动态形状，代价是短请求被填充到桶上限、浪费部分算力；收益是消除重编译尖峰。具体例子：流式生成中每帧请求长度递增，若按请求逐帧编译，首帧时延尖峰反复出现；改为按帧数分桶、桶内共享编译产物后，尖峰转移到桶边界，可用预编译预热把边界也压掉。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-43\">四十三 · 路由不均与尾延迟尖刺</h3>\n<p>序列并行轴上的“路由”不是网络路由，而是分片到设备的映射。按帧切分时，若帧间内容复杂度差异大（例如运动剧烈段与静止段），各分片的注意力计算量不均，WGMMA 占用率在设备间失衡；按空间块切分时，边缘块与中心块的 token 密度不同，同样造成不均。张量并行轴的 all-reduce 是同步点，任何一个分片慢都会把整批拖到最慢者，尾延迟尖刺由此产生。</p>\n<p>监控要按设备维度看两个量：分片计算时长与 all-gather/all-reduce 等待时长。判据是等待时长占比升高而计算时长平稳，说明瓶颈在同步而非算力。缓解手段包括按内容复杂度做分片重映射、把通信与 WGMMA 重叠的窗口拉长、以及在批调度层把长序列请求单独成批避免拖尾。具体例子：一段高分辨率长视频中段出现快速运动，按帧均分导致该段所在分片的注意力块显著变重，整批时延被它拉长；改为按帧的 token 数加权切分后，各分片计算量拉平，尾延迟尖刺消失，代价是切分边界不再与帧对齐，VAE 阶段需按新边界重排。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-44\">四十四 · 监控面与回滚阶梯</h3>\n<p>监控面要覆盖四个层次，且每层都要有可回滚的开关。第一层是分片级数值探针（局部 softmax 分母、all-reduce 前后范数、逐帧 VAE 均值），用于精度漂移；第二层是显存三类计数与峰值对齐事件，用于 OOM；第三层是编译缓存命中率与分片时长离散度，用于批抖动；第四层是设备级计算/等待时长比，用于路由不均与尾延迟。四层共用一条请求追踪 ID，才能在回滚时判断是哪一层先劣化。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要监控量</th><th>第一回滚动作</th><th>系统代价</th></tr></thead><tbody><tr><td>精度漂移</td><td>分片间统计量相对偏差</td><td>统一两阶段缩放因子，退回 FP8</td><td>重跑整条链路，占用跨节点带宽</td></tr><tr><td>OOM</td><td>激活/通信/重排缓冲峰值</td><td>降批与分片上限，加宽张量并行轴</td><td>时延上升，算力利用率下降</td></tr><tr><td>批抖动</td><td>编译缓存命中率、分片时长离散度</td><td>形状桶化，预编译预热</td><td>短请求填充浪费算力</td></tr><tr><td>路由不均</td><td>计算/等待时长比</td><td>按 token 数加权切分</td><td>切分边界错位，VAE 重排成本</td></tr></tbody></table>\n<p>回滚阶梯的原则是“先动形状、再动精度、最后动拓扑”。形状类回滚（批上限、桶化、分片上限）不改变数值路径，风险最低；精度类回滚（FP8 替代 NVFP4、统一缩放）改变数值但不动布局；拓扑类回滚（改 <span class=\"formula\">$$P_s$$</span> 或张量并行轴）会触发全量重编译与重排，代价最高且最容易引入新的接缝问题。每次回滚都要在探针上确认劣化层已恢复，而不是只看端到端时延回到 SLO。</p>\n<p>一个具体的工程判断：当跨节点 IB 带宽成为时延下限时，序列切分过多会让 all-gather 通信量随序列长度增长而压垮带宽，此时把 <span class=\"formula\">$$P_s$$</span> 继续调大是负收益，正确动作是把长视频请求按帧分块、在块边界做重叠融合，让单次 all-gather 的序列规模受控，同时保持 sharding annotation 在采样与 VAE 两阶段一致以避免运行期重排。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-45\">四十五 · 序列切分越界之后：通信、重排与重编译的三类尖刺怎么定位</h3>\n\n<p>这套方案真正的失效点不在稳态吞吐，而在“切分—通信—重排”三者耦合处的非线性劣化。最典型的失败模式是序列并行切分数超过互联可承受的临界点：注意力阶段每层都要对 $K,V$ 做 ring 或 all-gather 交换，通信量与序列切分数成正比，而单步时延由下式给出，其中 $\\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$ 随切分数 $P_s$ 与序列长度 $N$ 同时放大：</p>\n\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right)$$</div>\n\n<p>诊断上不要只看端到端时延，要按阶段拆出“计算项”与“通信项”：若 WGMMA 占用率随 $P_s$ 增大而下降、NVLink/IB 吞吐却持续贴顶，说明重叠已经失效，通信项接管了 $T_{\\text{step}}$。此时继续加卡只会让跨节点 IB 成为时延下限，正确动作是按序列长度设分片上限并回退到更少的序列切分、把余量转到张量并行轴。代价是显存占用上升，需同步收紧每卡序列分片与通信缓冲的批上限。</p>\n\n<p>第二类尖刺来自布局不一致导致的运行期全量重排。采样阶段 latent 切在序列并行轴，VAE 解码却要按帧走数据并行轴；若 sharding annotation 未统一，编译期融合失败，重排退化为运行期搬运，latent 在设备间反复往返，显存峰值与同步开销同时陡增。监控抓手是逐阶段的设备间字节计数与同步等待时间——正常融合时这两项应接近零，一旦出现与帧数成正比的搬运量即为退化信号。回滚路径是恢复统一布局注解、把像素留在解码所在节点，宁可牺牲一点采样侧并行度也不做跨节点像素传输。</p>\n\n<p>第三类是动态 batch 与变长请求触发的重编译尖峰：编译缓存未命中时首帧时延突刺，流式 SLO 在负载波动下失守。工程判断是把批上限与序列长度档位离散化，用有限档位换取缓存命中率，并在路由侧按档位而非按请求做亲和调度。下表给出三类失败模式的判别信号与代价落点：</p>\n\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>判别信号</th><th>代价落点</th><th>回滚动作</th></tr></thead><tbody><tr><td>序列切分过多</td><td>WGMMA 占用降、互联吞吐贴顶</td><td>跨节点带宽成时延下限</td><td>降 $P_s$、抬张量并行轴</td></tr><tr><td>布局不一致</td><td>阶段间字节计数随帧数增长</td><td>显存峰值与同步等待</td><td>统一 sharding 注解</td></tr><tr><td>重编译尖峰</td><td>缓存未命中率与首帧时延同涨</td><td>流式 SLO 违约</td><td>离散档位 + 按档路由</td></tr></tbody></table>\n\n<p>精度问题在这套拓扑里表现为分片边界上的数值漂移：FP8/NVFP4 量化后，all-reduce 与 ring 交换的累加顺序随切分数变化，残差本地累加虽避免了跨设备归约，但各分片的量化误差不再被同一归约路径抵消。诊断靠固定种子下比对不同 $P_s$ 的输出差异，若差异随切分数单调放大即定位到通信路径而非算子本身；回滚是固定归约顺序或对注意力交换段保留更高精度，代价是带宽占用上升。路由不均则表现为部分序列分片因帧内容复杂度不同而负载倾斜，尾延迟尖刺出现在最慢分片的 all-gather 等待上，需按分片实际计算量而非均分长度做切分。</p>\n<h3 id=\"alg-jax-mesh-parallel-video-sec-46\">四十六 · 对照轴：先分清“切什么”与“切在哪一层”</h3>\n<p>把本条目放回同族算法的坐标里，第一件要做的事不是比性能，而是比“切分对象”。视频 DiT 推理的并行方案可以沿两条正交的轴分类：一条是切分维度（序列/时空、权重、帧、请求），另一条是切分发生的层级（单卡内分块、单节点多卡、跨节点）。本条目占据的是“序列维 × 多卡/多节点”这一格，它的邻居各自占据不同的格，因此不存在谁替代谁的问题，只存在“当前负载落在哪一格”的问题。分块重叠解码切的是时间维但停在单卡显存层级，用重叠融合把窗口约束吃掉；朴素张量并行切权重、通信发生在每一层 GEMM 之后；VAE 分块重叠解码切的是像素域而非 latent 域；预填/解码分离切的是请求生命周期而非张量布局。判断时先问一句：瓶颈是单卡显存放不下 latent 序列，还是单卡算力不够、还是窗口机制本身受限？答案不同，选型立刻分叉。</p>\n<p>代价的量纲也不同。序列并行的通信项按 <span class=\"formula\">$$\\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</span> 随序列长度 N 线性增长，而张量并行的通信量大致与隐藏维和层数挂钩、与序列长度弱相关。这意味着短序列、大隐藏维的负载更适合张量并行；长序列、固定隐藏维的负载才轮到序列并行。把这条比例关系当成选型的第一道筛子，比事后调参有效得多。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-47\">四十七 · 决策表：五种形态的适用条件与代价落点</h3>\n<p>下表把同族形态按“切分对象—通信量纲—主要代价—失效信号”四列对齐，读者可据此做初筛。表中不写绝对数字，只写随负载变化的趋势，因为具体阈值取决于互联档位与模型形状。</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>切分对象</th><th>通信量随什么增长</th><th>主要代价落点</th><th>失效信号</th></tr></thead><tbody>\n<tr><td>本条目：序列并行 × 张量并行（JAX mesh）</td><td>latent 序列按帧/空间块；权重按头/通道</td><td>序列长度 N、序列切分数 P_s</td><td>跨节点 NVLink/IB 带宽；编译与布局调优</td><td>重叠不足以掩盖 all-gather；重编译尖峰</td></tr>\n<tr><td>分块重叠解码（时间分块）</td><td>时间维块，块间重叠融合</td><td>块数与重叠比例，不跨设备</td><td>单卡显存与重复计算</td><td>重叠区算力浪费超过窗口收益</td></tr>\n<tr><td>朴素张量并行</td><td>权重矩阵按行/列</td><td>层数 × 隐藏维，与 N 弱相关</td><td>每层 all-reduce 的同步时延</td><td>小 batch 下通信占比压过 GEMM</td></tr>\n<tr><td>VAE 分块重叠解码</td><td>像素域空间块</td><td>块边界 halo，不跨设备</td><td>解码阶段显存与接缝质量</td><td>接缝可见、halo 重复解码拖时延</td></tr>\n<tr><td>预填/解码分离服务</td><td>请求生命周期阶段</td><td>KV 传输量，与并发数相关</td><td>KV 跨池搬运带宽</td><td>KV 搬运时延吃掉分离收益</td></tr>\n</tbody></table>\n<p>读表的关键是第三列：通信量随 N 增长的形态在长视频上必然撞带宽墙，通信量与 N 弱相关的形态在长视频上反而稳定。因此“长视频 + 多节点”这一组合几乎只能落到本条目或分离式服务上，而后者解决的是并发调度问题、不是单请求显存问题。若单请求 latent 已超单卡容量，分离式服务无能为力，必须走序列并行。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-48\">四十八 · 选型判据：三个可计算的比值</h3>\n<p>决策表给出方向，落到具体配置还需要可计算的判据。第一条是显存比值：单卡可用显存与单请求 latent 加注意力工作集之比。若该比值小于 1，序列并行是唯一出路，此时讨论通信代价已无意义——不切就放不下。第二条是通信-计算比值，直接取自本系列的步时公式：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right)$$</div>\n<p>把序列切分数 P_s 代进 Comm 项，观察它是否已经顶到 max 的右支。若右支主导，说明再增加切分数只会让时延变差，此时应回退切分数或改用张量并行分担权重压力。第三条是编译可行性比值：动态 batch 上限与编译缓存命中率的乘积，决定重编译尖峰是否落在 SLO 预算内。流式场景下首帧时延对重编译极其敏感，若请求形态方差大，宁可牺牲部分并行度换取布局稳定。</p>\n<p>具体例子：一个高分辨率长时长、固定步数的生成请求，latent 序列远超单卡容量，互联为单节点 NVLink 域。此时显存比值小于 1，直接选序列并行；由于留在单节点内，Comm 项走 NVLink 而非 IB，重叠窗口足够，切分数可以取到使每卡分片刚好容纳工作集的档位。反之，若同一模型换成短序列、高并发的小请求，显存比值大于 1，序列并行的通信项纯属浪费，应退回张量并行加连续批处理，把并行度花在吞吐而非单请求时延上。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-49\">四十九 · 与分块重叠的接缝：窗口问题不等于容量问题</h3>\n<p>最容易混淆的一对是本条目与分块重叠解码。两者都切时间维，但目的不同：分块重叠解决的是注意力窗口装不下或跨块上下文断裂，切完仍在单卡内，靠重叠区融合保持连续性；序列并行解决的是整条 latent 序列在显存里放不下，切完跨设备，靠 ring/all-gather 交换 KV。判据很直接：如果单卡能装下整条序列、只是窗口机制导致必须分块，选分块重叠，不要引入任何跨设备通信；如果单卡装不下，分块重叠再省也省不出一个数量级，必须上序列并行。二者可以叠加，但叠加时要注意重叠区在序列并行下会放大 all-gather 的交换量——重叠比例越高，每块需要交换的 KV 边界越宽，Comm 项随之上升。工程上应先把重叠比例压到质量可接受的下限，再定序列切分数，顺序反了会得到一个通信量虚高的配置。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-50\">五十 · 与量化、稀疏、缓存的组合次序</h3>\n<p>同族里还有一批不改并行拓扑、只改数值与访问模式的算法：NVFP4/FP8 量化、动态稀疏时空注意力、轨迹感知缓存复用。它们与本条目的关系是“先减后切”还是“先切后减”，次序影响收益。量化降低每卡分片的激活与权重占用，等价于把显存比值往上推，可能让原本必须序列并行的负载退回单卡或减少切分数，因此量化应作为选型前的预处理评估：先估算量化后的显存比值，再决定是否切。稀疏注意力削减的是注意力块的 FLOPs，直接作用在步时公式的左支；若左支本就主导，稀疏化收益明显，若右支（通信）主导，稀疏化反而让计算更快、通信占比更高，加速比被通信吃掉。缓存复用减少的是重复步的 FLOPs，与序列并行正交，可叠加，但缓存命中导致的变长执行会加剧重编译问题，需要在编译缓存策略上预留余量。组合次序的经验规则：先量化压显存、再判是否需要切、切完再看左支是否值得稀疏化。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-51\">五十一 · 规模上限与回退路径</h3>\n<p>本条目的规模上限由两个量共同封顶：跨节点互联带宽与编译可行性。序列切分数 P_s 增大时，每卡分片变小、计算时间缩短，但 Comm 项按 N/P_s 的比例关系并不自动下降——交换的 KV 总量与序列长度同阶，切得越细，单位计算对应的通信占比越高。存在一个最优点，使 max 的两支大致相等；超过该点继续加卡，时延不降反升。工程判断是：先把单节点 NVLink 域内的切分数用满，再考虑跨节点，因为跨节点把 Comm 项从 NVLink 换成 IB，量级差异直接改变最优点的位置。回退路径有两条：一是降分辨率或降时长，把 N 压回显存比值大于 1 的区间，退回单卡分块重叠；二是把权重压力从序列并行里剥离，改用张量并行承担，序列并行只负责显存分摊，让两条通信路径各自处在自己的量纲上。回退的触发信号应写进监控：当 all-gather 等待时间占步时的比例持续上升、或编译缓存未命中率在负载波动时抬升，就执行回退，而不是继续加卡。</p>\n\n<h3 id=\"alg-jax-mesh-parallel-video-sec-52\">五十二 · 选型边界：序列并行、时间分块与朴素张量并行的三岔口</h3>\n<p>本方案与相邻算法的分野不在“能不能切”，而在“切哪一维、通信落在哪条链路上”。分块重叠走的是时间维：把长视频切成时间块，在块边界做重叠融合，用固定窗口反复迭代，显存占用与序列长度解耦，代价是块间上下文丢失与重复计算，适合单节点、窗口受限、对跨块一致性容忍度高的场景。朴素张量并行切的是权重维，每层 GEMM 后必做 all-reduce，通信量随层数与隐藏维固定增长，与序列长度无关；序列短、模型宽时它是干净的选择，但注意力窗口本身没被突破，长视频 latent 仍可能单卡放不下。本方案切序列维，把注意力窗口和激活显存一并摊到 mesh 上，代价是通信量随切分数增长。三者可用同一条 roofline 判据粗筛：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(\\frac{\\text{FLOPs}}{P\\cdot \\text{TC}},\\ \\frac{\\text{Bytes}}{\\text{BW}}+\\frac{\\text{Comm}}{\\text{NVLink}}\\right),\\quad \\text{Comm}_{\\text{attn}}\\propto \\frac{N}{P_s}\\,d\\,N_h$$</div>\n<p>其中 $N$ 为 latent 序列长度、$P_s$ 为序列并行度。$N/P_s$ 不变时增加 $P_s$ 只摊薄显存、不减少单卡注意力通信；$N$ 增长则通信线性上涨。判断落在哪一侧：若第二项已被 Bytes/BW 主导，序列并行近乎免费；若 Comm 项抬头，说明切过头了。工程上先固定 $P_s$ 使每卡分片刚好装下 KV 与激活，再增加张量并行度补算力，而不是反过来。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>首选</th><th>失效信号</th></tr></thead><tbody><tr><td>短序列、宽模型、单节点</td><td>张量并行</td><td>注意力窗口仍溢出显存</td></tr><tr><td>超长序列、窗口受限、单节点</td><td>时间分块重叠</td><td>块边界闪烁、重复算力占比高</td></tr><tr><td>高分辨率长视频、多节点互联</td><td>序列并行＋张量并行</td><td>跨节点 IB 带宽打满、重叠掩盖不住</td></tr><tr><td>采样与 VAE 同流程</td><td>统一 sharding 布局</td><td>阶段间全量重排、像素跨节点搬运</td></tr></tbody></table>\n<p>失效条件要盯三处。其一，序列切分过多使 ring 或 all-gather 的 KV 交换量超过 WGMMA 可重叠的窗口，跨节点 IB 成为时延下限，此时应减少 $P_s$、改用节点内 NVLink 域承载注意力通信，把跨节点流量留给 FFN 的 all-reduce。其二，采样与 VAE 的 sharding annotation 不一致，编译期融合失败退化为运行期全量重排，latent 在设备间反复搬运，显存与同步开销陡增——这正是统一布局存在的理由，也是本方案相对“采样一套并行、解码另一套并行”的朴素实现的核心增量。其三，动态 batch 与变长请求触发重编译，编译缓存未命中时首帧时延出现尖峰，流式 SLO 守不住；折中是设批上限与分片上限，把变长请求 padding 到桶内，用少量算力换编译稳定性。系统代价上，本方案换来的是显存与窗口的线性扩展，付出的是通信随长度增长与编译调优的人力成本；小模型或短序列下，通信开销会直接吃掉收益，此时退回张量并行或时间分块更划算。两条机制线的支撑见 paper-vidax-a-unified-jax-framework-for-vi-2026 与 paper-ultra-flash-scaling-real-time-stream-2026。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 多卡并行与加速器网格编排</td></tr><tr><td>解决什么</td><td>高分辨率长视频DiT单卡放不下或时延不达标，需要多卡/多节点并行；视频序列在时空上可切分，但朴素张量并行通信量大，且V…</td></tr><tr><td>一句话机制</td><td>在JAX mesh上把序列维按时空块做序列并行、权重按张量并行切分，注意力用环形/全收集通信重叠计算，VAE解码按帧做…</td></tr><tr><td>代价与失效</td><td>序列并行通信量随序列长度增长，跨节点时NVLink/IB带宽可能成为瓶颈。；JAX编译与sharding布局调优成本高，动态batch/变…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-jax-mesh-parallel-video · 共 8 个片段</p>\n";break;}}})();
